/* ============================================================
   GlobalStone — Shared Stylesheet
   ============================================================ */

/* ---- Custom Properties ---- */
:root {
  --navy:       #0A1628;
  --navy-light: #0f2040;
  --navy-mid:   #152a52;
  --gold:       #C9A84C;
  --gold-light: #dfc06e;
  --gold-dark:  #a8882d;
  --white:      #ffffff;
  --gray-50:    #f9fafb;
  --gray-100:   #f3f4f6;
  --gray-200:   #e5e7eb;
  --gray-300:   #d1d5db;
  --gray-400:   #9ca3af;
  --gray-500:   #6b7280;
  --gray-600:   #4b5563;
  --gray-700:   #374151;
  --gray-800:   #1f2937;
  --text:       #1a2035;
  --font-sans:  'Inter', system-ui, -apple-system, sans-serif;
  --shadow-sm:  0 1px 3px rgba(0,0,0,.08), 0 1px 2px rgba(0,0,0,.05);
  --shadow-md:  0 4px 16px rgba(0,0,0,.1);
  --shadow-lg:  0 12px 40px rgba(0,0,0,.16);
  --transition: 220ms cubic-bezier(.4,0,.2,1);
  --container:  1280px;
  --radius:     4px;
}

/* ---- Reset ---- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; -webkit-text-size-adjust: 100%; }
body {
  font-family: var(--font-sans);
  font-size: 16px;
  line-height: 1.6;
  color: var(--text);
  background: var(--white);
  -webkit-font-smoothing: antialiased;
}
img { max-width: 100%; height: auto; display: block; }
a { color: inherit; text-decoration: none; }
ul, ol { list-style: none; }
button { cursor: pointer; border: none; background: none; font: inherit; }
input, textarea, select { font: inherit; }

/* ---- Layout ---- */
.container {
  width: 100%;
  max-width: var(--container);
  margin: 0 auto;
  padding: 0 24px;
}

/* ---- Typography ---- */
h1, h2, h3, h4, h5 {
  font-weight: 700;
  line-height: 1.2;
  letter-spacing: -0.02em;
  color: var(--navy);
}
h1 { font-size: clamp(2rem, 5vw, 3.5rem); }
h2 { font-size: clamp(1.75rem, 3.5vw, 2.75rem); }
h3 { font-size: clamp(1.25rem, 2.5vw, 1.75rem); }
h4 { font-size: 1.125rem; font-weight: 600; }
h5 { font-size: 0.875rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.1em; }
p { color: var(--gray-600); line-height: 1.75; }
.lead { font-size: 1.125rem; color: var(--gray-500); }

/* ---- Buttons ---- */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 13px 28px;
  font-size: 0.875rem;
  font-weight: 600;
  letter-spacing: 0.03em;
  border-radius: var(--radius);
  transition: var(--transition);
  white-space: nowrap;
}
.btn-primary {
  background: var(--gold);
  color: var(--navy);
}
.btn-primary:hover {
  background: var(--gold-light);
  transform: translateY(-1px);
  box-shadow: 0 8px 24px rgba(201,168,76,.35);
}
.btn-outline {
  background: transparent;
  color: var(--white);
  border: 1.5px solid rgba(255,255,255,.6);
}
.btn-outline:hover {
  background: rgba(255,255,255,.1);
  border-color: var(--white);
}
.btn-outline-dark {
  background: transparent;
  color: var(--navy);
  border: 1.5px solid var(--navy);
}
.btn-outline-dark:hover {
  background: var(--navy);
  color: var(--white);
}
.btn-ghost {
  padding: 0;
  color: var(--gold);
  font-weight: 600;
  font-size: 0.875rem;
}
.btn-ghost:hover { color: var(--gold-dark); }
.btn-ghost::after { content: ' →'; }

/* ---- Tag / Label ---- */
.tag {
  display: inline-block;
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  padding: 3px 10px;
  border-radius: 2px;
}
.tag-gold { background: rgba(201,168,76,.15); color: var(--gold-dark); }
.tag-navy { background: var(--navy); color: var(--white); }
.tag-gray { background: var(--gray-100); color: var(--gray-600); }

/* ============================================================
   HEADER / NAVIGATION
   ============================================================ */
.site-header {
  position: fixed;
  top: 0; left: 0; right: 0;
  z-index: 1000;
  background: var(--navy);
  border-bottom: 1px solid rgba(255,255,255,.08);
  transition: box-shadow var(--transition);
}
.site-header.scrolled {
  box-shadow: 0 4px 30px rgba(0,0,0,.4);
}
.header-inner {
  display: flex;
  align-items: center;
  height: 72px;
  gap: 40px;
}

/* Logo */
.logo {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-shrink: 0;
  text-decoration: none;
}
.logo-mark {
  width: 36px;
  height: 36px;
  background: var(--gold);
  border-radius: 3px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.logo-mark svg { width: 20px; height: 20px; fill: var(--navy); }
.logo-text {
  font-size: 1.1rem;
  font-weight: 800;
  color: var(--white);
  letter-spacing: 0.04em;
}
.logo-sub {
  display: block;
  font-size: 0.55rem;
  font-weight: 500;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: rgba(255,255,255,.5);
  margin-top: 1px;
}

/* Primary nav */
.primary-nav { flex: 1; display: flex; justify-content: center; }
.nav-list {
  display: flex;
  align-items: center;
  gap: 4px;
}
.nav-item { position: relative; }
.nav-link {
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 8px 14px;
  font-size: 0.875rem;
  font-weight: 500;
  color: rgba(255,255,255,.8);
  border-radius: var(--radius);
  transition: color var(--transition), background var(--transition);
  white-space: nowrap;
}
.nav-link:hover, .nav-link.active {
  color: var(--white);
  background: rgba(255,255,255,.08);
}
.nav-link .chevron {
  width: 14px;
  height: 14px;
  transition: transform var(--transition);
  opacity: .6;
}
.nav-item.open .nav-link .chevron { transform: rotate(180deg); }

/* Header actions */
.header-actions {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-shrink: 0;
}
.header-search {
  width: 32px; height: 32px;
  display: flex; align-items: center; justify-content: center;
  color: rgba(255,255,255,.6);
  border-radius: var(--radius);
  transition: var(--transition);
}
.header-search:hover { color: var(--white); background: rgba(255,255,255,.1); }
.header-search svg { width: 17px; height: 17px; }

/* Hamburger */
.hamburger {
  display: none;
  flex-direction: column;
  justify-content: center;
  gap: 5px;
  width: 36px;
  height: 36px;
  padding: 6px;
}
.hamburger span {
  display: block;
  height: 2px;
  background: var(--white);
  border-radius: 2px;
  transition: var(--transition);
}
.hamburger.open span:nth-child(1) { transform: rotate(45deg) translate(5px, 5px); }
.hamburger.open span:nth-child(2) { opacity: 0; }
.hamburger.open span:nth-child(3) { transform: rotate(-45deg) translate(5px, -5px); }

/* ============================================================
   MEGA MENU
   ============================================================ */
.mega-menu {
  position: absolute;
  top: calc(100% + 8px);
  left: 50%;
  transform: translateX(-50%);
  width: 620px;
  background: var(--white);
  border-radius: 8px;
  box-shadow: var(--shadow-lg);
  border: 1px solid var(--gray-200);
  padding: 28px;
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transform: translateX(-50%) translateY(-8px);
  transition: opacity 200ms ease, transform 200ms ease, visibility 200ms;
}
.mega-menu::before {
  content: '';
  position: absolute;
  top: -6px; left: 50%;
  transform: translateX(-50%);
  border: 6px solid transparent;
  border-top: 0;
  border-bottom-color: var(--white);
}
.nav-item.open .mega-menu,
.nav-item:hover .mega-menu {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
  transform: translateX(-50%) translateY(0);
}
.mega-menu-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 32px;
}
.mega-col-title {
  font-size: 0.65rem;
  font-weight: 700;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--gray-400);
  margin-bottom: 12px;
  padding-bottom: 8px;
  border-bottom: 1px solid var(--gray-200);
}
.mega-link {
  display: block;
  padding: 7px 0;
  font-size: 0.875rem;
  color: var(--gray-700);
  border-bottom: 1px solid transparent;
  transition: color var(--transition);
}
.mega-link:hover { color: var(--navy); font-weight: 600; }
.mega-link-featured {
  font-weight: 600;
  color: var(--navy);
}

/* ============================================================
   MOBILE NAV
   ============================================================ */
.mobile-nav {
  display: none;
  position: fixed;
  top: 72px; left: 0; right: 0; bottom: 0;
  background: var(--navy);
  overflow-y: auto;
  z-index: 999;
  padding: 20px 24px 40px;
}
.mobile-nav.open { display: block; }

.mobile-nav-item { border-bottom: 1px solid rgba(255,255,255,.08); }
.mobile-nav-toggle {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 16px 0;
  color: var(--white);
  font-size: 1rem;
  font-weight: 500;
  text-align: left;
}
.mobile-nav-toggle .chevron {
  width: 16px; height: 16px;
  transition: transform var(--transition);
  opacity: .5;
}
.mobile-nav-item.open .mobile-nav-toggle .chevron { transform: rotate(180deg); }
.mobile-sub {
  display: none;
  padding: 0 0 16px 16px;
}
.mobile-nav-item.open .mobile-sub { display: block; }
.mobile-sub-title {
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--gold);
  margin: 12px 0 8px;
}
.mobile-sub a {
  display: block;
  padding: 8px 0;
  font-size: 0.9rem;
  color: rgba(255,255,255,.7);
}
.mobile-sub a:hover { color: var(--white); }
.mobile-plain-link {
  display: block;
  padding: 16px 0;
  color: var(--white);
  font-size: 1rem;
  font-weight: 500;
  border-bottom: 1px solid rgba(255,255,255,.08);
}

/* ============================================================
   HERO SECTIONS
   ============================================================ */
.hero {
  position: relative;
  min-height: 620px;
  display: flex;
  align-items: center;
  overflow: hidden;
  margin-top: 72px;
}
.hero-bg {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, #0A1628 0%, #0d2742 45%, #152a52 100%);
}
.hero-bg::after {
  content: '';
  position: absolute;
  inset: 0;
  background: url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%23ffffff' fill-opacity='0.03'%3E%3Cpath d='M36 34v-4h-2v4h-4v2h4v4h2v-4h4v-2h-4zm0-30V0h-2v4h-4v2h4v4h2V6h4V4h-4zM6 34v-4H4v4H0v2h4v4h2v-4h4v-2H6zM6 4V0H4v4H0v2h4v4h2V6h4V4H6z'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E");
}
.hero-accent {
  position: absolute;
  bottom: -80px; right: -80px;
  width: 500px; height: 500px;
  background: radial-gradient(circle, rgba(201,168,76,.12) 0%, transparent 70%);
  border-radius: 50%;
}
.hero-accent-2 {
  position: absolute;
  top: -60px; left: 20%;
  width: 400px; height: 400px;
  background: radial-gradient(circle, rgba(255,255,255,.04) 0%, transparent 70%);
  border-radius: 50%;
}
.hero-content {
  position: relative;
  z-index: 1;
  max-width: 760px;
  padding: 80px 0;
}
.hero-eyebrow {
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--gold);
  margin-bottom: 20px;
}
.hero h1 { color: var(--white); margin-bottom: 20px; }
.hero .lead { color: rgba(255,255,255,.75); margin-bottom: 36px; max-width: 580px; }
.hero-actions { display: flex; gap: 14px; flex-wrap: wrap; }

/* Interior page hero */
.hero-interior { min-height: 380px; }
.hero-interior .hero-content { padding: 60px 0; }
.hero-interior h1 { font-size: clamp(1.75rem, 4vw, 2.75rem); }

/* Hero image variant */
.hero-with-image { background: none; }
.hero-with-image .hero-bg {
  background: linear-gradient(105deg, #071020 0%, #0a1628 60%, #0f1f3d 100%);
}

/* ============================================================
   SECTIONS — SHARED
   ============================================================ */
.section { padding: 96px 0; }
.section-sm { padding: 64px 0; }
.section-lg { padding: 120px 0; }
.section-dark { background: var(--navy); }
.section-dark h2, .section-dark h3, .section-dark h4 { color: var(--white); }
.section-dark p { color: rgba(255,255,255,.65); }
.section-gray { background: var(--gray-50); }
.section-header { margin-bottom: 56px; }
.section-header.centered { text-align: center; }
.section-header p { margin-top: 12px; max-width: 640px; }
.section-header.centered p { margin-inline: auto; }
.eyebrow {
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--gold);
  margin-bottom: 12px;
  display: block;
}

/* ============================================================
   FEATURED INSIGHTS — HOMEPAGE
   ============================================================ */
.featured-insights { padding: 64px 0; background: var(--gray-50); }
.insights-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}
.insight-card {
  background: var(--white);
  border-radius: 6px;
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--gray-200);
  transition: transform var(--transition), box-shadow var(--transition);
  display: flex;
  flex-direction: column;
}
.insight-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
}
.insight-card-img {
  aspect-ratio: 16/10;
  position: relative;
  overflow: hidden;
}
.insight-card-img-bg {
  position: absolute; inset: 0;
  background: linear-gradient(135deg, var(--navy) 0%, var(--navy-mid) 100%);
}
.insight-card-img-bg.var-1 { background: linear-gradient(135deg, #0f2040 0%, #1a3461 100%); }
.insight-card-img-bg.var-2 { background: linear-gradient(135deg, #0d1f38 0%, #152a52 100%); }
.insight-card-img-bg.var-3 { background: linear-gradient(135deg, #071020 0%, #0f2040 100%); }
.insight-card-img-bg::before {
  content: '';
  position: absolute; inset: 0;
  background: url("data:image/svg+xml,%3Csvg width='80' height='80' viewBox='0 0 80 80' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='%23ffffff' fill-opacity='0.05'%3E%3Cpath fill-rule='evenodd' d='M11 0l5 20H6l5-20zm42 31a3 3 0 1 0 0-6 3 3 0 0 0 0 6zM0 72h40v4H0v-4zm0-8h31.999v4H0v-4zm20-16h20v4H20v-4zM0 56h40v4H0v-4zm63-25a3 3 0 1 0 0-6 3 3 0 0 0 0 6zm10 0a3 3 0 1 0 0-6 3 3 0 0 0 0 6zM34 0l5 20h-9l4-20zm-4 0l5 20h-9l4-20zM21 0l5 20h-9l4-20z'/%3E%3C/g%3E%3C/svg%3E");
}
.insight-card-body { padding: 24px; flex: 1; display: flex; flex-direction: column; }
.insight-card-type {
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--gold-dark);
  margin-bottom: 10px;
}
.insight-card-body h4 {
  font-size: 1rem;
  font-weight: 600;
  color: var(--navy);
  line-height: 1.4;
  margin-bottom: 12px;
  flex: 1;
}
.insight-card-body .btn-ghost { margin-top: auto; }

/* ============================================================
   ANNOUNCEMENT BANNER
   ============================================================ */
.announcement-banner {
  background: var(--gold);
  padding: 16px 0;
}
.banner-inner {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 20px;
  text-align: center;
}
.banner-inner p {
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--navy);
  margin: 0;
}
.banner-cta {
  font-size: 0.8rem;
  font-weight: 700;
  color: var(--navy);
  text-decoration: underline;
  white-space: nowrap;
}
.banner-cta:hover { opacity: .7; }

/* ============================================================
   ABOUT STATEMENT
   ============================================================ */
.about-statement { padding: 96px 0; }
.about-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  align-items: center;
}
.about-text h2 { margin-bottom: 20px; }
.about-text p { margin-bottom: 32px; font-size: 1.05rem; }
.about-visual {
  position: relative;
  aspect-ratio: 4/3;
  border-radius: 8px;
  overflow: hidden;
}
.about-visual-bg {
  position: absolute; inset: 0;
  background: linear-gradient(135deg, var(--navy) 0%, var(--navy-mid) 50%, #1e3a6e 100%);
}
.about-visual-bg::before {
  content: '';
  position: absolute; inset: 0;
  background: url("data:image/svg+xml,%3Csvg width='100' height='100' viewBox='0 0 100 100' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M11 18c3.866 0 7-3.134 7-7s-3.134-7-7-7-7 3.134-7 7 3.134 7 7 7zm48 25c3.866 0 7-3.134 7-7s-3.134-7-7-7-7 3.134-7 7 3.134 7 7 7zm-43-7c1.657 0 3-1.343 3-3s-1.343-3-3-3-3 1.343-3 3 1.343 3 3 3zm63 31c1.657 0 3-1.343 3-3s-1.343-3-3-3-3 1.343-3 3 1.343 3 3 3zM34 90c1.657 0 3-1.343 3-3s-1.343-3-3-3-3 1.343-3 3 1.343 3 3 3zm56-76c1.657 0 3-1.343 3-3s-1.343-3-3-3-3 1.343-3 3 1.343 3 3 3zM12 86c2.21 0 4-1.79 4-4s-1.79-4-4-4-4 1.79-4 4 1.79 4 4 4zm28-65c2.21 0 4-1.79 4-4s-1.79-4-4-4-4 1.79-4 4 1.79 4 4 4zm23-11c2.76 0 5-2.24 5-5s-2.24-5-5-5-5 2.24-5 5 2.24 5 5 5zm-6 60c2.21 0 4-1.79 4-4s-1.79-4-4-4-4 1.79-4 4 1.79 4 4 4zm29 22c2.76 0 5-2.24 5-5s-2.24-5-5-5-5 2.24-5 5 2.24 5 5 5zM32 63c2.76 0 5-2.24 5-5s-2.24-5-5-5-5 2.24-5 5 2.24 5 5 5zm57-13c2.76 0 5-2.24 5-5s-2.24-5-5-5-5 2.24-5 5 2.24 5 5 5zm-9-21c1.105 0 2-.895 2-2s-.895-2-2-2-2 .895-2 2 .895 2 2 2zM60 91c1.105 0 2-.895 2-2s-.895-2-2-2-2 .895-2 2 .895 2 2 2zM35 41c1.105 0 2-.895 2-2s-.895-2-2-2-2 .895-2 2 .895 2 2 2z' fill='%23ffffff' fill-opacity='0.06' fill-rule='evenodd'/%3E%3C/svg%3E");
}
.about-stat-row {
  position: absolute;
  bottom: 0; left: 0; right: 0;
  background: rgba(10,22,40,.85);
  backdrop-filter: blur(8px);
  padding: 20px 24px;
  display: flex;
  gap: 32px;
}
.about-stat-num {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--gold);
  display: block;
}
.about-stat-label {
  font-size: 0.75rem;
  color: rgba(255,255,255,.6);
  letter-spacing: 0.03em;
}

/* ============================================================
   WHAT WE DO — TABBED SECTION
   ============================================================ */
.what-we-do { background: var(--gray-50); padding: 96px 0; }
.tabs-layout {
  display: grid;
  grid-template-columns: 260px 1fr;
  gap: 0;
  background: var(--white);
  border-radius: 8px;
  overflow: hidden;
  box-shadow: var(--shadow-md);
  border: 1px solid var(--gray-200);
}
.tab-nav {
  background: var(--navy);
  display: flex;
  flex-direction: column;
}
.tab-btn {
  padding: 28px 28px;
  text-align: left;
  color: rgba(255,255,255,.6);
  font-size: 0.9rem;
  font-weight: 500;
  border-left: 3px solid transparent;
  transition: var(--transition);
  border-bottom: 1px solid rgba(255,255,255,.06);
}
.tab-btn:hover { color: var(--white); background: rgba(255,255,255,.05); }
.tab-btn.active {
  color: var(--white);
  border-left-color: var(--gold);
  background: rgba(255,255,255,.08);
}
.tab-btn span {
  display: block;
  font-size: 0.65rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--gold);
  margin-bottom: 6px;
  font-weight: 700;
}
.tab-panel { display: none; padding: 48px; flex-direction: column; justify-content: center; }
.tab-panel.active { display: flex; }
.tab-panel h3 { color: var(--navy); margin-bottom: 16px; }
.tab-panel p { font-size: 1rem; margin-bottom: 32px; max-width: 500px; }

/* ============================================================
   NEWSLETTER SECTION
   ============================================================ */
.newsletter-section { background: var(--navy); padding: 72px 0; }
.newsletter-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 40px;
}
.newsletter-text h2 { color: var(--white); margin-bottom: 10px; }
.newsletter-text p { color: rgba(255,255,255,.65); max-width: 480px; }
.newsletter-form { display: flex; gap: 0; max-width: 420px; width: 100%; }
.newsletter-input {
  flex: 1;
  padding: 14px 18px;
  background: rgba(255,255,255,.08);
  border: 1px solid rgba(255,255,255,.2);
  border-right: 0;
  border-radius: 4px 0 0 4px;
  color: var(--white);
  font-size: 0.875rem;
  outline: none;
  transition: border-color var(--transition);
}
.newsletter-input::placeholder { color: rgba(255,255,255,.4); }
.newsletter-input:focus { border-color: var(--gold); }
.newsletter-btn {
  padding: 14px 24px;
  background: var(--gold);
  color: var(--navy);
  font-size: 0.875rem;
  font-weight: 700;
  border-radius: 0 4px 4px 0;
  transition: background var(--transition);
  white-space: nowrap;
}
.newsletter-btn:hover { background: var(--gold-light); }

/* ============================================================
   LATEST INSIGHTS
   ============================================================ */
.latest-insights-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 28px;
}
.insight-row-card {
  display: flex;
  flex-direction: column;
  border: 1px solid var(--gray-200);
  border-radius: 6px;
  overflow: hidden;
  transition: box-shadow var(--transition), transform var(--transition);
}
.insight-row-card:hover { box-shadow: var(--shadow-md); transform: translateY(-3px); }
.insight-row-img {
  aspect-ratio: 16/9;
  position: relative;
  overflow: hidden;
}
.insight-row-img-bg { position: absolute; inset: 0; }
.insight-row-body { padding: 24px; flex: 1; display: flex; flex-direction: column; }
.insight-row-meta {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 12px;
  flex-wrap: wrap;
}
.insight-row-meta .date {
  font-size: 0.75rem;
  color: var(--gray-400);
}
.insight-row-body h4 {
  font-size: 1rem;
  line-height: 1.4;
  color: var(--navy);
  margin-bottom: 16px;
  flex: 1;
}
.insight-row-body .btn-ghost::after { content: ' →'; }

/* ============================================================
   OUR COMMITMENT
   ============================================================ */
.commitment-section { padding: 96px 0; background: var(--gray-50); }
.commitment-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}
.commitment-card {
  background: var(--white);
  border-radius: 6px;
  padding: 36px 28px;
  border: 1px solid var(--gray-200);
  transition: var(--transition);
}
.commitment-card:hover { box-shadow: var(--shadow-md); transform: translateY(-4px); }
.commitment-icon {
  width: 48px; height: 48px;
  background: rgba(201,168,76,.12);
  border-radius: 8px;
  display: flex; align-items: center; justify-content: center;
  margin-bottom: 20px;
}
.commitment-icon svg { width: 22px; height: 22px; stroke: var(--gold-dark); fill: none; stroke-width: 1.5; }
.commitment-card h4 { margin-bottom: 12px; }
.commitment-card p { font-size: 0.875rem; margin-bottom: 20px; }

/* ============================================================
   SERVICE CATEGORIES GRID
   ============================================================ */
.service-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 28px;
}
.service-card {
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: 8px;
  padding: 36px 32px;
  display: flex;
  flex-direction: column;
  transition: var(--transition);
  position: relative;
  overflow: hidden;
}
.service-card::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 3px;
  background: var(--gold);
  transform: scaleX(0);
  transition: transform var(--transition);
}
.service-card:hover { box-shadow: var(--shadow-lg); transform: translateY(-4px); }
.service-card:hover::before { transform: scaleX(1); }
.service-card-num {
  font-size: 2.5rem;
  font-weight: 800;
  color: rgba(201,168,76,.2);
  line-height: 1;
  margin-bottom: 16px;
  font-variant-numeric: tabular-nums;
}
.service-card h3 { font-size: 1.2rem; margin-bottom: 12px; }
.service-card p { font-size: 0.9rem; flex: 1; margin-bottom: 24px; }

/* ============================================================
   CAPABILITIES GRID
   ============================================================ */
.capabilities-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}
.capability-card {
  padding: 32px 28px;
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: 6px;
  transition: var(--transition);
}
.capability-card:hover { box-shadow: var(--shadow-md); border-color: var(--gold); }
.capability-card h4 { margin-bottom: 10px; color: var(--navy); }
.capability-card p { font-size: 0.875rem; }

/* ============================================================
   FEATURED PARTNERS / CAROUSEL
   ============================================================ */
.carousel-section { background: var(--gray-50); padding: 80px 0; }
.carousel-wrapper { position: relative; overflow: hidden; }
.carousel-track {
  display: flex;
  gap: 24px;
  transition: transform 400ms cubic-bezier(.4,0,.2,1);
}
.carousel-slide {
  min-width: calc(33.333% - 16px);
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: 8px;
  padding: 32px;
  flex-shrink: 0;
}
.carousel-slide h4 { margin-bottom: 10px; }
.carousel-slide p { font-size: 0.875rem; }
.carousel-controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  margin-top: 32px;
}
.carousel-btn {
  width: 44px; height: 44px;
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  background: var(--white);
  border: 1.5px solid var(--gray-300);
  color: var(--navy);
  transition: var(--transition);
}
.carousel-btn:hover { background: var(--navy); border-color: var(--navy); color: var(--white); }
.carousel-btn svg { width: 18px; height: 18px; }

/* ============================================================
   TESTIMONIAL
   ============================================================ */
.testimonial-section { padding: 80px 0; background: var(--navy); }
.testimonial-inner { max-width: 800px; margin: 0 auto; text-align: center; }
.testimonial-quote {
  font-size: 1.4rem;
  font-style: italic;
  font-weight: 300;
  color: rgba(255,255,255,.9);
  line-height: 1.6;
  margin-bottom: 28px;
}
.testimonial-quote::before { content: '\201C'; }
.testimonial-quote::after  { content: '\201D'; }
.testimonial-author { color: var(--gold); font-weight: 600; font-size: 0.9rem; }
.testimonial-role { color: rgba(255,255,255,.5); font-size: 0.8rem; margin-top: 4px; }

/* ============================================================
   FEATURED TOPICS / SIDEBAR
   ============================================================ */
.featured-topics-section { padding: 80px 0; }
.topics-layout {
  display: grid;
  grid-template-columns: 2fr 1fr;
  gap: 60px;
  align-items: start;
}
.topics-list { }
.topic-item {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 20px 0;
  border-bottom: 1px solid var(--gray-200);
  color: var(--navy);
  font-weight: 500;
  transition: color var(--transition);
}
.topic-item:hover { color: var(--gold-dark); }
.topic-num {
  font-size: 0.8rem;
  color: var(--gold);
  font-weight: 700;
  min-width: 28px;
}
.topics-sidebar { background: var(--gray-50); border-radius: 8px; padding: 28px; }
.topics-sidebar h5 { margin-bottom: 20px; color: var(--navy); }
.topics-sidebar a {
  display: block;
  padding: 10px 0;
  font-size: 0.875rem;
  color: var(--navy);
  border-bottom: 1px solid var(--gray-200);
  transition: color var(--transition);
}
.topics-sidebar a:hover { color: var(--gold-dark); }

/* ============================================================
   CTA BANDS
   ============================================================ */
.cta-band {
  background: linear-gradient(135deg, var(--navy) 0%, var(--navy-mid) 100%);
  padding: 80px 0;
  text-align: center;
}
.cta-band h2 { color: var(--white); margin-bottom: 16px; }
.cta-band p { color: rgba(255,255,255,.65); margin-bottom: 36px; max-width: 560px; margin-inline: auto; }
.cta-band .btn-group { display: flex; gap: 14px; justify-content: center; flex-wrap: wrap; }
.cta-band-gold { background: var(--gold); }
.cta-band-gold h2 { color: var(--navy); }
.cta-band-gold p { color: rgba(10,22,40,.7); }

/* Property types */
.property-types-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 16px;
  margin-top: 48px;
}
.property-type-card {
  background: rgba(255,255,255,.08);
  border: 1px solid rgba(255,255,255,.12);
  border-radius: 6px;
  padding: 24px 16px;
  text-align: center;
  color: rgba(255,255,255,.8);
  font-size: 0.875rem;
  font-weight: 500;
  transition: var(--transition);
}
.property-type-card:hover { background: rgba(255,255,255,.14); color: var(--white); }
.property-type-icon { font-size: 1.8rem; margin-bottom: 8px; }

/* Related services */
.related-services-section { padding: 80px 0; }
.related-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}
.related-card {
  padding: 28px;
  border: 1px solid var(--gray-200);
  border-radius: 6px;
  transition: var(--transition);
}
.related-card:hover { box-shadow: var(--shadow-md); border-color: rgba(201,168,76,.4); }
.related-card h4 { font-size: 1rem; margin-bottom: 8px; }
.related-card p { font-size: 0.85rem; margin-bottom: 16px; }

/* ============================================================
   PARTNERSHIP HIGHLIGHT
   ============================================================ */
.partnership-section { background: var(--gray-50); padding: 80px 0; }
.partnership-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}
.stat-chips { display: flex; gap: 20px; margin-top: 32px; flex-wrap: wrap; }
.stat-chip {
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: 8px;
  padding: 20px 24px;
  text-align: center;
  min-width: 120px;
}
.stat-chip-num { font-size: 2rem; font-weight: 800; color: var(--gold-dark); display: block; }
.stat-chip-label { font-size: 0.75rem; color: var(--gray-500); }

/* ============================================================
   FOOTER
   ============================================================ */
.site-footer {
  background: var(--navy);
  padding: 72px 0 0;
  border-top: 1px solid rgba(255,255,255,.08);
}
.footer-grid {
  display: grid;
  grid-template-columns: 260px repeat(4, 1fr);
  gap: 40px;
  padding-bottom: 56px;
}
.footer-brand .logo { margin-bottom: 16px; }
.footer-brand p { color: rgba(255,255,255,.45); font-size: 0.8rem; line-height: 1.7; max-width: 200px; }
.footer-col h5 {
  font-size: 0.65rem;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: rgba(255,255,255,.35);
  margin-bottom: 16px;
  padding-bottom: 8px;
  border-bottom: 1px solid rgba(255,255,255,.08);
}
.footer-col a {
  display: block;
  padding: 5px 0;
  font-size: 0.85rem;
  color: rgba(255,255,255,.55);
  transition: color var(--transition);
}
.footer-col a:hover { color: var(--white); }
.footer-bottom {
  border-top: 1px solid rgba(255,255,255,.08);
  padding: 20px 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  flex-wrap: wrap;
}
.footer-bottom p { font-size: 0.78rem; color: rgba(255,255,255,.3); margin: 0; }
.footer-legal { display: flex; gap: 20px; flex-wrap: wrap; }
.footer-legal a { font-size: 0.78rem; color: rgba(255,255,255,.3); transition: color var(--transition); }
.footer-legal a:hover { color: rgba(255,255,255,.6); }

/* ============================================================
   INTRO STATEMENT BLOCK
   ============================================================ */
.intro-statement { padding: 64px 0; border-bottom: 1px solid var(--gray-200); }
.intro-statement-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  align-items: center;
}
.intro-statement h2 { margin-bottom: 16px; }
.intro-statement p { font-size: 1.05rem; }

/* ============================================================
   RESPONSIVE
   ============================================================ */
@media (max-width: 1024px) {
  .footer-grid { grid-template-columns: 1fr 1fr; gap: 32px; }
  .about-inner { grid-template-columns: 1fr; gap: 48px; }
  .about-visual { max-height: 300px; }
  .intro-statement-inner { grid-template-columns: 1fr; gap: 32px; }
  .topics-layout { grid-template-columns: 1fr; }
  .partnership-inner { grid-template-columns: 1fr; gap: 40px; }
}

@media (max-width: 900px) {
  .primary-nav { display: none; }
  .hamburger { display: flex; }
  .mega-menu { display: none !important; }

  .header-actions .btn { display: none; }

  .insights-grid { grid-template-columns: 1fr 1fr; }
  .service-grid { grid-template-columns: 1fr 1fr; }
  .commitment-grid { grid-template-columns: 1fr 1fr; }
  .capabilities-grid { grid-template-columns: 1fr 1fr; }
  .latest-insights-grid { grid-template-columns: 1fr 1fr; }
  .related-grid { grid-template-columns: 1fr; }
  .property-types-grid { grid-template-columns: repeat(3, 1fr); }
  .carousel-slide { min-width: calc(50% - 12px); }
}

@media (max-width: 640px) {
  .section { padding: 64px 0; }
  .section-lg { padding: 80px 0; }
  h1 { font-size: 1.75rem; }
  h2 { font-size: 1.5rem; }
  .hero { min-height: 520px; }
  .hero-content { padding: 56px 0; }
  .insights-grid { grid-template-columns: 1fr; }
  .service-grid { grid-template-columns: 1fr; }
  .commitment-grid { grid-template-columns: 1fr; }
  .capabilities-grid { grid-template-columns: 1fr; }
  .latest-insights-grid { grid-template-columns: 1fr; }
  .property-types-grid { grid-template-columns: repeat(2, 1fr); }
  .newsletter-inner { flex-direction: column; align-items: flex-start; }
  .newsletter-form { flex-direction: column; max-width: 100%; }
  .newsletter-input { border-right: 1px solid rgba(255,255,255,.2); border-radius: 4px; }
  .newsletter-btn { border-radius: 4px; }
  .banner-inner { flex-direction: column; gap: 8px; }
  .tabs-layout { grid-template-columns: 1fr; }
  .tab-nav { flex-direction: row; overflow-x: auto; }
  .tab-btn { padding: 16px 20px; border-left: 0; border-bottom: 3px solid transparent; min-width: 140px; }
  .tab-btn.active { border-left: 0; border-bottom-color: var(--gold); }
  .tab-panel { padding: 28px 24px; }
  .about-stat-row { flex-direction: column; gap: 12px; }
  .carousel-slide { min-width: 100%; }
  .cta-band { padding: 56px 0; }
  .footer-grid { grid-template-columns: 1fr 1fr; gap: 28px; }
  .footer-bottom { flex-direction: column; align-items: flex-start; }
  .hero-actions { flex-direction: column; align-items: flex-start; }
}

/* ============================================================
   UTILITY
   ============================================================ */
.divider { height: 1px; background: var(--gray-200); margin: 0; }
.text-gold { color: var(--gold); }
.text-white { color: var(--white); }
.mt-auto { margin-top: auto; }
.visually-hidden { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }

/* ============================================================
   GlobalStone — Shared Stylesheet
   ============================================================ */

/* ---- Custom Properties ---- */
:root {
  --navy:       #0A1628;
  --navy-light: #0f2040;
  --navy-mid:   #152a52;
  --gold:       #C9A84C;
  --gold-light: #dfc06e;
  --gold-dark:  #a8882d;
  --white:      #ffffff;
  --gray-50:    #f9fafb;
  --gray-100:   #f3f4f6;
  --gray-200:   #e5e7eb;
  --gray-300:   #d1d5db;
  --gray-400:   #9ca3af;
  --gray-500:   #6b7280;
  --gray-600:   #4b5563;
  --gray-700:   #374151;
  --gray-800:   #1f2937;
  --text:       #1a2035;
  --font-sans:  'Inter', system-ui, -apple-system, sans-serif;
  --shadow-sm:  0 1px 3px rgba(0,0,0,.08), 0 1px 2px rgba(0,0,0,.05);
  --shadow-md:  0 4px 16px rgba(0,0,0,.1);
  --shadow-lg:  0 12px 40px rgba(0,0,0,.16);
  --transition: 220ms cubic-bezier(.4,0,.2,1);
  --container:  1280px;
  --radius:     4px;
}

/* ---- Reset ---- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; -webkit-text-size-adjust: 100%; }
body {
  font-family: var(--font-sans);
  font-size: 16px;
  line-height: 1.6;
  color: var(--text);
  background: var(--white);
  -webkit-font-smoothing: antialiased;
}
img { max-width: 100%; height: auto; display: block; }
a { color: inherit; text-decoration: none; }
ul, ol { list-style: none; }
button { cursor: pointer; border: none; background: none; font: inherit; }
input, textarea, select { font: inherit; }

/* ---- Layout ---- */
.container {
  width: 100%;
  max-width: var(--container);
  margin: 0 auto;
  padding: 0 24px;
}

/* ---- Typography ---- */
h1, h2, h3, h4, h5 {
  font-weight: 700;
  line-height: 1.2;
  letter-spacing: -0.02em;
  color: var(--navy);
}
h1 { font-size: clamp(2rem, 5vw, 3.5rem); }
h2 { font-size: clamp(1.75rem, 3.5vw, 2.75rem); }
h3 { font-size: clamp(1.25rem, 2.5vw, 1.75rem); }
h4 { font-size: 1.125rem; font-weight: 600; }
h5 { font-size: 0.875rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.1em; }
p { color: var(--gray-600); line-height: 1.75; }
.lead { font-size: 1.125rem; color: var(--gray-500); }

/* ---- Buttons ---- */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 13px 28px;
  font-size: 0.875rem;
  font-weight: 600;
  letter-spacing: 0.03em;
  border-radius: var(--radius);
  transition: var(--transition);
  white-space: nowrap;
}
.btn-primary {
  background: var(--gold);
  color: var(--navy);
}
.btn-primary:hover {
  background: var(--gold-light);
  transform: translateY(-1px);
  box-shadow: 0 8px 24px rgba(201,168,76,.35);
}
.btn-outline {
  background: transparent;
  color: var(--white);
  border: 1.5px solid rgba(255,255,255,.6);
}
.btn-outline:hover {
  background: rgba(255,255,255,.1);
  border-color: var(--white);
}
.btn-outline-dark {
  background: transparent;
  color: var(--navy);
  border: 1.5px solid var(--navy);
}
.btn-outline-dark:hover {
  background: var(--navy);
  color: var(--white);
}
.btn-ghost {
  padding: 0;
  color: var(--gold);
  font-weight: 600;
  font-size: 0.875rem;
}
.btn-ghost:hover { color: var(--gold-dark); }
.btn-ghost::after { content: ' →'; }

/* ---- Tag / Label ---- */
.tag {
  display: inline-block;
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  padding: 3px 10px;
  border-radius: 2px;
}
.tag-gold { background: rgba(201,168,76,.15); color: var(--gold-dark); }
.tag-navy { background: var(--navy); color: var(--white); }
.tag-gray { background: var(--gray-100); color: var(--gray-600); }

/* ============================================================
   HEADER / NAVIGATION
   ============================================================ */
.site-header {
  position: fixed;
  top: 0; left: 0; right: 0;
  z-index: 1000;
  background: var(--navy);
  border-bottom: 1px solid rgba(255,255,255,.08);
  transition: box-shadow var(--transition);
}
.site-header.scrolled {
  box-shadow: 0 4px 30px rgba(0,0,0,.4);
}
.header-inner {
  display: flex;
  align-items: center;
  height: 72px;
  gap: 40px;
}

/* Logo */
.logo {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-shrink: 0;
  text-decoration: none;
}
.logo-mark {
  width: 36px;
  height: 36px;
  background: var(--gold);
  border-radius: 3px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.logo-mark svg { width: 20px; height: 20px; fill: var(--navy); }
.logo-text {
  font-size: 1.1rem;
  font-weight: 800;
  color: var(--white);
  letter-spacing: 0.04em;
}
.logo-sub {
  display: block;
  font-size: 0.55rem;
  font-weight: 500;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: rgba(255,255,255,.5);
  margin-top: 1px;
}

/* Primary nav */
.primary-nav { flex: 1; display: flex; justify-content: center; }
.nav-list {
  display: flex;
  align-items: center;
  gap: 4px;
}
.nav-item { position: relative; }
.nav-link {
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 8px 14px;
  font-size: 0.875rem;
  font-weight: 500;
  color: rgba(255,255,255,.8);
  border-radius: var(--radius);
  transition: color var(--transition), background var(--transition);
  white-space: nowrap;
}
.nav-link:hover, .nav-link.active {
  color: var(--white);
  background: rgba(255,255,255,.08);
}
.nav-link .chevron {
  width: 14px;
  height: 14px;
  transition: transform var(--transition);
  opacity: .6;
}
.nav-item.open .nav-link .chevron { transform: rotate(180deg); }

/* Header actions */
.header-actions {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-shrink: 0;
}
.header-search {
  width: 32px; height: 32px;
  display: flex; align-items: center; justify-content: center;
  color: rgba(255,255,255,.6);
  border-radius: var(--radius);
  transition: var(--transition);
}
.header-search:hover { color: var(--white); background: rgba(255,255,255,.1); }
.header-search svg { width: 17px; height: 17px; }

/* Hamburger */
.hamburger {
  display: none;
  flex-direction: column;
  justify-content: center;
  gap: 5px;
  width: 36px;
  height: 36px;
  padding: 6px;
}
.hamburger span {
  display: block;
  height: 2px;
  background: var(--white);
  border-radius: 2px;
  transition: var(--transition);
}
.hamburger.open span:nth-child(1) { transform: rotate(45deg) translate(5px, 5px); }
.hamburger.open span:nth-child(2) { opacity: 0; }
.hamburger.open span:nth-child(3) { transform: rotate(-45deg) translate(5px, -5px); }

/* ============================================================
   MEGA MENU
   ============================================================ */
.mega-menu {
  position: absolute;
  top: calc(100% + 8px);
  left: 50%;
  transform: translateX(-50%);
  width: 620px;
  background: var(--white);
  border-radius: 8px;
  box-shadow: var(--shadow-lg);
  border: 1px solid var(--gray-200);
  padding: 28px;
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transform: translateX(-50%) translateY(-8px);
  transition: opacity 200ms ease, transform 200ms ease, visibility 200ms;
}
.mega-menu::before {
  content: '';
  position: absolute;
  top: -6px; left: 50%;
  transform: translateX(-50%);
  border: 6px solid transparent;
  border-top: 0;
  border-bottom-color: var(--white);
}
.nav-item.open .mega-menu,
.nav-item:hover .mega-menu {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
  transform: translateX(-50%) translateY(0);
}
.mega-menu-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 32px;
}
.mega-col-title {
  font-size: 0.65rem;
  font-weight: 700;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--gray-400);
  margin-bottom: 12px;
  padding-bottom: 8px;
  border-bottom: 1px solid var(--gray-200);
}
.mega-link {
  display: block;
  padding: 7px 0;
  font-size: 0.875rem;
  color: var(--gray-700);
  border-bottom: 1px solid transparent;
  transition: color var(--transition);
}
.mega-link:hover { color: var(--navy); font-weight: 600; }
.mega-link-featured {
  font-weight: 600;
  color: var(--navy);
}

/* ============================================================
   MOBILE NAV
   ============================================================ */
.mobile-nav {
  display: none;
  position: fixed;
  top: 72px; left: 0; right: 0; bottom: 0;
  background: var(--navy);
  overflow-y: auto;
  z-index: 999;
  padding: 20px 24px 40px;
}
.mobile-nav.open { display: block; }

.mobile-nav-item { border-bottom: 1px solid rgba(255,255,255,.08); }
.mobile-nav-toggle {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 16px 0;
  color: var(--white);
  font-size: 1rem;
  font-weight: 500;
  text-align: left;
}
.mobile-nav-toggle .chevron {
  width: 16px; height: 16px;
  transition: transform var(--transition);
  opacity: .5;
}
.mobile-nav-item.open .mobile-nav-toggle .chevron { transform: rotate(180deg); }
.mobile-sub {
  display: none;
  padding: 0 0 16px 16px;
}
.mobile-nav-item.open .mobile-sub { display: block; }
.mobile-sub-title {
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--gold);
  margin: 12px 0 8px;
}
.mobile-sub a {
  display: block;
  padding: 8px 0;
  font-size: 0.9rem;
  color: rgba(255,255,255,.7);
}
.mobile-sub a:hover { color: var(--white); }
.mobile-plain-link {
  display: block;
  padding: 16px 0;
  color: var(--white);
  font-size: 1rem;
  font-weight: 500;
  border-bottom: 1px solid rgba(255,255,255,.08);
}

/* ============================================================
   HERO SECTIONS
   ============================================================ */
.hero {
  position: relative;
  min-height: 620px;
  display: flex;
  align-items: center;
  overflow: hidden;
  margin-top: 72px;
}
.hero-bg {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, #0A1628 0%, #0d2742 45%, #152a52 100%);
}
.hero-bg::after {
  content: '';
  position: absolute;
  inset: 0;
  background: url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%23ffffff' fill-opacity='0.03'%3E%3Cpath d='M36 34v-4h-2v4h-4v2h4v4h2v-4h4v-2h-4zm0-30V0h-2v4h-4v2h4v4h2V6h4V4h-4zM6 34v-4H4v4H0v2h4v4h2v-4h4v-2H6zM6 4V0H4v4H0v2h4v4h2V6h4V4H6z'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E");
}
.hero-accent {
  position: absolute;
  bottom: -80px; right: -80px;
  width: 500px; height: 500px;
  background: radial-gradient(circle, rgba(201,168,76,.12) 0%, transparent 70%);
  border-radius: 50%;
}
.hero-accent-2 {
  position: absolute;
  top: -60px; left: 20%;
  width: 400px; height: 400px;
  background: radial-gradient(circle, rgba(255,255,255,.04) 0%, transparent 70%);
  border-radius: 50%;
}
.hero-content {
  position: relative;
  z-index: 1;
  max-width: 760px;
  padding: 80px 0;
}
.hero-eyebrow {
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--gold);
  margin-bottom: 20px;
}
.hero h1 { color: var(--white); margin-bottom: 20px; }
.hero .lead { color: rgba(255,255,255,.75); margin-bottom: 36px; max-width: 580px; }
.hero-actions { display: flex; gap: 14px; flex-wrap: wrap; }

/* Interior page hero */
.hero-interior { min-height: 380px; }
.hero-interior .hero-content { padding: 60px 0; }
.hero-interior h1 { font-size: clamp(1.75rem, 4vw, 2.75rem); }

/* Hero image variant */
.hero-with-image { background: none; }
.hero-with-image .hero-bg {
  background: linear-gradient(105deg, #071020 0%, #0a1628 60%, #0f1f3d 100%);
}

/* ============================================================
   SECTIONS — SHARED
   ============================================================ */
.section { padding: 96px 0; }
.section-sm { padding: 64px 0; }
.section-lg { padding: 120px 0; }
.section-dark { background: var(--navy); }
.section-dark h2, .section-dark h3, .section-dark h4 { color: var(--white); }
.section-dark p { color: rgba(255,255,255,.65); }
.section-gray { background: var(--gray-50); }
.section-header { margin-bottom: 56px; }
.section-header.centered { text-align: center; }
.section-header p { margin-top: 12px; max-width: 640px; }
.section-header.centered p { margin-inline: auto; }
.eyebrow {
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--gold);
  margin-bottom: 12px;
  display: block;
}

/* ============================================================
   FEATURED INSIGHTS — HOMEPAGE
   ============================================================ */
.featured-insights { padding: 64px 0; background: var(--gray-50); }
.insights-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}
.insight-card {
  background: var(--white);
  border-radius: 6px;
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--gray-200);
  transition: transform var(--transition), box-shadow var(--transition);
  display: flex;
  flex-direction: column;
}
.insight-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
}
.insight-card-img {
  aspect-ratio: 16/10;
  position: relative;
  overflow: hidden;
}
.insight-card-img-bg {
  position: absolute; inset: 0;
  background: linear-gradient(135deg, var(--navy) 0%, var(--navy-mid) 100%);
}
.insight-card-img-bg.var-1 { background: linear-gradient(135deg, #0f2040 0%, #1a3461 100%); }
.insight-card-img-bg.var-2 { background: linear-gradient(135deg, #0d1f38 0%, #152a52 100%); }
.insight-card-img-bg.var-3 { background: linear-gradient(135deg, #071020 0%, #0f2040 100%); }
.insight-card-img-bg::before {
  content: '';
  position: absolute; inset: 0;
  background: url("data:image/svg+xml,%3Csvg width='80' height='80' viewBox='0 0 80 80' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='%23ffffff' fill-opacity='0.05'%3E%3Cpath fill-rule='evenodd' d='M11 0l5 20H6l5-20zm42 31a3 3 0 1 0 0-6 3 3 0 0 0 0 6zM0 72h40v4H0v-4zm0-8h31.999v4H0v-4zm20-16h20v4H20v-4zM0 56h40v4H0v-4zm63-25a3 3 0 1 0 0-6 3 3 0 0 0 0 6zm10 0a3 3 0 1 0 0-6 3 3 0 0 0 0 6zM34 0l5 20h-9l4-20zm-4 0l5 20h-9l4-20zM21 0l5 20h-9l4-20z'/%3E%3C/g%3E%3C/svg%3E");
}
.insight-card-body { padding: 24px; flex: 1; display: flex; flex-direction: column; }
.insight-card-type {
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--gold-dark);
  margin-bottom: 10px;
}
.insight-card-body h4 {
  font-size: 1rem;
  font-weight: 600;
  color: var(--navy);
  line-height: 1.4;
  margin-bottom: 12px;
  flex: 1;
}
.insight-card-body .btn-ghost { margin-top: auto; }

/* ============================================================
   ANNOUNCEMENT BANNER
   ============================================================ */
.announcement-banner {
  background: var(--gold);
  padding: 16px 0;
}
.banner-inner {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 20px;
  text-align: center;
}
.banner-inner p {
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--navy);
  margin: 0;
}
.banner-cta {
  font-size: 0.8rem;
  font-weight: 700;
  color: var(--navy);
  text-decoration: underline;
  white-space: nowrap;
}
.banner-cta:hover { opacity: .7; }

/* ============================================================
   ABOUT STATEMENT
   ============================================================ */
.about-statement { padding: 96px 0; }
.about-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  align-items: center;
}
.about-text h2 { margin-bottom: 20px; }
.about-text p { margin-bottom: 32px; font-size: 1.05rem; }
.about-visual {
  position: relative;
  aspect-ratio: 4/3;
  border-radius: 8px;
  overflow: hidden;
}
.about-visual-bg {
  position: absolute; inset: 0;
  background: linear-gradient(135deg, var(--navy) 0%, var(--navy-mid) 50%, #1e3a6e 100%);
}
.about-visual-bg::before {
  content: '';
  position: absolute; inset: 0;
  background: url("data:image/svg+xml,%3Csvg width='100' height='100' viewBox='0 0 100 100' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M11 18c3.866 0 7-3.134 7-7s-3.134-7-7-7-7 3.134-7 7 3.134 7 7 7zm48 25c3.866 0 7-3.134 7-7s-3.134-7-7-7-7 3.134-7 7 3.134 7 7 7zm-43-7c1.657 0 3-1.343 3-3s-1.343-3-3-3-3 1.343-3 3 1.343 3 3 3zm63 31c1.657 0 3-1.343 3-3s-1.343-3-3-3-3 1.343-3 3 1.343 3 3 3zM34 90c1.657 0 3-1.343 3-3s-1.343-3-3-3-3 1.343-3 3 1.343 3 3 3zm56-76c1.657 0 3-1.343 3-3s-1.343-3-3-3-3 1.343-3 3 1.343 3 3 3zM12 86c2.21 0 4-1.79 4-4s-1.79-4-4-4-4 1.79-4 4 1.79 4 4 4zm28-65c2.21 0 4-1.79 4-4s-1.79-4-4-4-4 1.79-4 4 1.79 4 4 4zm23-11c2.76 0 5-2.24 5-5s-2.24-5-5-5-5 2.24-5 5 2.24 5 5 5zm-6 60c2.21 0 4-1.79 4-4s-1.79-4-4-4-4 1.79-4 4 1.79 4 4 4zm29 22c2.76 0 5-2.24 5-5s-2.24-5-5-5-5 2.24-5 5 2.24 5 5 5zM32 63c2.76 0 5-2.24 5-5s-2.24-5-5-5-5 2.24-5 5 2.24 5 5 5zm57-13c2.76 0 5-2.24 5-5s-2.24-5-5-5-5 2.24-5 5 2.24 5 5 5zm-9-21c1.105 0 2-.895 2-2s-.895-2-2-2-2 .895-2 2 .895 2 2 2zM60 91c1.105 0 2-.895 2-2s-.895-2-2-2-2 .895-2 2 .895 2 2 2zM35 41c1.105 0 2-.895 2-2s-.895-2-2-2-2 .895-2 2 .895 2 2 2z' fill='%23ffffff' fill-opacity='0.06' fill-rule='evenodd'/%3E%3C/svg%3E");
}
.about-stat-row {
  position: absolute;
  bottom: 0; left: 0; right: 0;
  background: rgba(10,22,40,.85);
  backdrop-filter: blur(8px);
  padding: 20px 24px;
  display: flex;
  gap: 32px;
}
.about-stat-num {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--gold);
  display: block;
}
.about-stat-label {
  font-size: 0.75rem;
  color: rgba(255,255,255,.6);
  letter-spacing: 0.03em;
}

/* ============================================================
   WHAT WE DO — TABBED SECTION
   ============================================================ */
.what-we-do { background: var(--gray-50); padding: 96px 0; }
.tabs-layout {
  display: grid;
  grid-template-columns: 260px 1fr;
  gap: 0;
  background: var(--white);
  border-radius: 8px;
  overflow: hidden;
  box-shadow: var(--shadow-md);
  border: 1px solid var(--gray-200);
}
.tab-nav {
  background: var(--navy);
  display: flex;
  flex-direction: column;
}
.tab-btn {
  padding: 28px 28px;
  text-align: left;
  color: rgba(255,255,255,.6);
  font-size: 0.9rem;
  font-weight: 500;
  border-left: 3px solid transparent;
  transition: var(--transition);
  border-bottom: 1px solid rgba(255,255,255,.06);
}
.tab-btn:hover { color: var(--white); background: rgba(255,255,255,.05); }
.tab-btn.active {
  color: var(--white);
  border-left-color: var(--gold);
  background: rgba(255,255,255,.08);
}
.tab-btn span {
  display: block;
  font-size: 0.65rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--gold);
  margin-bottom: 6px;
  font-weight: 700;
}
.tab-panel { display: none; padding: 48px; flex-direction: column; justify-content: center; }
.tab-panel.active { display: flex; }
.tab-panel h3 { color: var(--navy); margin-bottom: 16px; }
.tab-panel p { font-size: 1rem; margin-bottom: 32px; max-width: 500px; }

/* ============================================================
   NEWSLETTER SECTION
   ============================================================ */
.newsletter-section { background: var(--navy); padding: 72px 0; }
.newsletter-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 40px;
}
.newsletter-text h2 { color: var(--white); margin-bottom: 10px; }
.newsletter-text p { color: rgba(255,255,255,.65); max-width: 480px; }
.newsletter-form { display: flex; gap: 0; max-width: 420px; width: 100%; }
.newsletter-input {
  flex: 1;
  padding: 14px 18px;
  background: rgba(255,255,255,.08);
  border: 1px solid rgba(255,255,255,.2);
  border-right: 0;
  border-radius: 4px 0 0 4px;
  color: var(--white);
  font-size: 0.875rem;
  outline: none;
  transition: border-color var(--transition);
}
.newsletter-input::placeholder { color: rgba(255,255,255,.4); }
.newsletter-input:focus { border-color: var(--gold); }
.newsletter-btn {
  padding: 14px 24px;
  background: var(--gold);
  color: var(--navy);
  font-size: 0.875rem;
  font-weight: 700;
  border-radius: 0 4px 4px 0;
  transition: background var(--transition);
  white-space: nowrap;
}
.newsletter-btn:hover { background: var(--gold-light); }

/* ============================================================
   LATEST INSIGHTS
   ============================================================ */
.latest-insights-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 28px;
}
.insight-row-card {
  display: flex;
  flex-direction: column;
  border: 1px solid var(--gray-200);
  border-radius: 6px;
  overflow: hidden;
  transition: box-shadow var(--transition), transform var(--transition);
}
.insight-row-card:hover { box-shadow: var(--shadow-md); transform: translateY(-3px); }
.insight-row-img {
  aspect-ratio: 16/9;
  position: relative;
  overflow: hidden;
}
.insight-row-img-bg { position: absolute; inset: 0; }
.insight-row-body { padding: 24px; flex: 1; display: flex; flex-direction: column; }
.insight-row-meta {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 12px;
  flex-wrap: wrap;
}
.insight-row-meta .date {
  font-size: 0.75rem;
  color: var(--gray-400);
}
.insight-row-body h4 {
  font-size: 1rem;
  line-height: 1.4;
  color: var(--navy);
  margin-bottom: 16px;
  flex: 1;
}
.insight-row-body .btn-ghost::after { content: ' →'; }

/* ============================================================
   OUR COMMITMENT
   ============================================================ */
.commitment-section { padding: 96px 0; background: var(--gray-50); }
.commitment-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}
.commitment-card {
  background: var(--white);
  border-radius: 6px;
  padding: 36px 28px;
  border: 1px solid var(--gray-200);
  transition: var(--transition);
}
.commitment-card:hover { box-shadow: var(--shadow-md); transform: translateY(-4px); }
.commitment-icon {
  width: 48px; height: 48px;
  background: rgba(201,168,76,.12);
  border-radius: 8px;
  display: flex; align-items: center; justify-content: center;
  margin-bottom: 20px;
}
.commitment-icon svg { width: 22px; height: 22px; stroke: var(--gold-dark); fill: none; stroke-width: 1.5; }
.commitment-card h4 { margin-bottom: 12px; }
.commitment-card p { font-size: 0.875rem; margin-bottom: 20px; }

/* ============================================================
   SERVICE CATEGORIES GRID
   ============================================================ */
.service-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 28px;
}
.service-card {
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: 8px;
  padding: 36px 32px;
  display: flex;
  flex-direction: column;
  transition: var(--transition);
  position: relative;
  overflow: hidden;
}
.service-card::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 3px;
  background: var(--gold);
  transform: scaleX(0);
  transition: transform var(--transition);
}
.service-card:hover { box-shadow: var(--shadow-lg); transform: translateY(-4px); }
.service-card:hover::before { transform: scaleX(1); }
.service-card-num {
  font-size: 2.5rem;
  font-weight: 800;
  color: rgba(201,168,76,.2);
  line-height: 1;
  margin-bottom: 16px;
  font-variant-numeric: tabular-nums;
}
.service-card h3 { font-size: 1.2rem; margin-bottom: 12px; }
.service-card p { font-size: 0.9rem; flex: 1; margin-bottom: 24px; }

/* ============================================================
   CAPABILITIES GRID
   ============================================================ */
.capabilities-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}
.capability-card {
  padding: 32px 28px;
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: 6px;
  transition: var(--transition);
}
.capability-card:hover { box-shadow: var(--shadow-md); border-color: var(--gold); }
.capability-card h4 { margin-bottom: 10px; color: var(--navy); }
.capability-card p { font-size: 0.875rem; }

/* ============================================================
   FEATURED PARTNERS / CAROUSEL
   ============================================================ */
.carousel-section { background: var(--gray-50); padding: 80px 0; }
.carousel-wrapper { position: relative; overflow: hidden; }
.carousel-track {
  display: flex;
  gap: 24px;
  transition: transform 400ms cubic-bezier(.4,0,.2,1);
}
.carousel-slide {
  min-width: calc(33.333% - 16px);
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: 8px;
  padding: 32px;
  flex-shrink: 0;
}
.carousel-slide h4 { margin-bottom: 10px; }
.carousel-slide p { font-size: 0.875rem; }
.carousel-controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  margin-top: 32px;
}
.carousel-btn {
  width: 44px; height: 44px;
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  background: var(--white);
  border: 1.5px solid var(--gray-300);
  color: var(--navy);
  transition: var(--transition);
}
.carousel-btn:hover { background: var(--navy); border-color: var(--navy); color: var(--white); }
.carousel-btn svg { width: 18px; height: 18px; }

/* ============================================================
   TESTIMONIAL
   ============================================================ */
.testimonial-section { padding: 80px 0; background: var(--navy); }
.testimonial-inner { max-width: 800px; margin: 0 auto; text-align: center; }
.testimonial-quote {
  font-size: 1.4rem;
  font-style: italic;
  font-weight: 300;
  color: rgba(255,255,255,.9);
  line-height: 1.6;
  margin-bottom: 28px;
}
.testimonial-quote::before { content: '\201C'; }
.testimonial-quote::after  { content: '\201D'; }
.testimonial-author { color: var(--gold); font-weight: 600; font-size: 0.9rem; }
.testimonial-role { color: rgba(255,255,255,.5); font-size: 0.8rem; margin-top: 4px; }

/* ============================================================
   FEATURED TOPICS / SIDEBAR
   ============================================================ */
.featured-topics-section { padding: 80px 0; }
.topics-layout {
  display: grid;
  grid-template-columns: 2fr 1fr;
  gap: 60px;
  align-items: start;
}
.topics-list { }
.topic-item {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 20px 0;
  border-bottom: 1px solid var(--gray-200);
  color: var(--navy);
  font-weight: 500;
  transition: color var(--transition);
}
.topic-item:hover { color: var(--gold-dark); }
.topic-num {
  font-size: 0.8rem;
  color: var(--gold);
  font-weight: 700;
  min-width: 28px;
}
.topics-sidebar { background: var(--gray-50); border-radius: 8px; padding: 28px; }
.topics-sidebar h5 { margin-bottom: 20px; color: var(--navy); }
.topics-sidebar a {
  display: block;
  padding: 10px 0;
  font-size: 0.875rem;
  color: var(--navy);
  border-bottom: 1px solid var(--gray-200);
  transition: color var(--transition);
}
.topics-sidebar a:hover { color: var(--gold-dark); }

/* ============================================================
   CTA BANDS
   ============================================================ */
.cta-band {
  background: linear-gradient(135deg, var(--navy) 0%, var(--navy-mid) 100%);
  padding: 80px 0;
  text-align: center;
}
.cta-band h2 { color: var(--white); margin-bottom: 16px; }
.cta-band p { color: rgba(255,255,255,.65); margin-bottom: 36px; max-width: 560px; margin-inline: auto; }
.cta-band .btn-group { display: flex; gap: 14px; justify-content: center; flex-wrap: wrap; }
.cta-band-gold { background: var(--gold); }
.cta-band-gold h2 { color: var(--navy); }
.cta-band-gold p { color: rgba(10,22,40,.7); }

/* Property types */
.property-types-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 16px;
  margin-top: 48px;
}
.property-type-card {
  background: rgba(255,255,255,.08);
  border: 1px solid rgba(255,255,255,.12);
  border-radius: 6px;
  padding: 24px 16px;
  text-align: center;
  color: rgba(255,255,255,.8);
  font-size: 0.875rem;
  font-weight: 500;
  transition: var(--transition);
}
.property-type-card:hover { background: rgba(255,255,255,.14); color: var(--white); }
.property-type-icon { font-size: 1.8rem; margin-bottom: 8px; }

/* Related services */
.related-services-section { padding: 80px 0; }
.related-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}
.related-card {
  padding: 28px;
  border: 1px solid var(--gray-200);
  border-radius: 6px;
  transition: var(--transition);
}
.related-card:hover { box-shadow: var(--shadow-md); border-color: rgba(201,168,76,.4); }
.related-card h4 { font-size: 1rem; margin-bottom: 8px; }
.related-card p { font-size: 0.85rem; margin-bottom: 16px; }

/* ============================================================
   PARTNERSHIP HIGHLIGHT
   ============================================================ */
.partnership-section { background: var(--gray-50); padding: 80px 0; }
.partnership-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}
.stat-chips { display: flex; gap: 20px; margin-top: 32px; flex-wrap: wrap; }
.stat-chip {
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: 8px;
  padding: 20px 24px;
  text-align: center;
  min-width: 120px;
}
.stat-chip-num { font-size: 2rem; font-weight: 800; color: var(--gold-dark); display: block; }
.stat-chip-label { font-size: 0.75rem; color: var(--gray-500); }

/* ============================================================
   FOOTER
   ============================================================ */
.site-footer {
  background: var(--navy);
  padding: 72px 0 0;
  border-top: 1px solid rgba(255,255,255,.08);
}
.footer-grid {
  display: grid;
  grid-template-columns: 260px repeat(4, 1fr);
  gap: 40px;
  padding-bottom: 56px;
}
.footer-brand .logo { margin-bottom: 16px; }
.footer-brand p { color: rgba(255,255,255,.45); font-size: 0.8rem; line-height: 1.7; max-width: 200px; }
.footer-col h5 {
  font-size: 0.65rem;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: rgba(255,255,255,.35);
  margin-bottom: 16px;
  padding-bottom: 8px;
  border-bottom: 1px solid rgba(255,255,255,.08);
}
.footer-col a {
  display: block;
  padding: 5px 0;
  font-size: 0.85rem;
  color: rgba(255,255,255,.55);
  transition: color var(--transition);
}
.footer-col a:hover { color: var(--white); }
.footer-bottom {
  border-top: 1px solid rgba(255,255,255,.08);
  padding: 20px 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  flex-wrap: wrap;
}
.footer-bottom p { font-size: 0.78rem; color: rgba(255,255,255,.3); margin: 0; }
.footer-legal { display: flex; gap: 20px; flex-wrap: wrap; }
.footer-legal a { font-size: 0.78rem; color: rgba(255,255,255,.3); transition: color var(--transition); }
.footer-legal a:hover { color: rgba(255,255,255,.6); }

/* ============================================================
   INTRO STATEMENT BLOCK
   ============================================================ */
.intro-statement { padding: 64px 0; border-bottom: 1px solid var(--gray-200); }
.intro-statement-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  align-items: center;
}
.intro-statement h2 { margin-bottom: 16px; }
.intro-statement p { font-size: 1.05rem; }

/* ============================================================
   RESPONSIVE
   ============================================================ */
@media (max-width: 1024px) {
  .footer-grid { grid-template-columns: 1fr 1fr; gap: 32px; }
  .about-inner { grid-template-columns: 1fr; gap: 48px; }
  .about-visual { max-height: 300px; }
  .intro-statement-inner { grid-template-columns: 1fr; gap: 32px; }
  .topics-layout { grid-template-columns: 1fr; }
  .partnership-inner { grid-template-columns: 1fr; gap: 40px; }
}

@media (max-width: 900px) {
  .primary-nav { display: none; }
  .hamburger { display: flex; }
  .mega-menu { display: none !important; }

  .header-actions .btn { display: none; }

  .insights-grid { grid-template-columns: 1fr 1fr; }
  .service-grid { grid-template-columns: 1fr 1fr; }
  .commitment-grid { grid-template-columns: 1fr 1fr; }
  .capabilities-grid { grid-template-columns: 1fr 1fr; }
  .latest-insights-grid { grid-template-columns: 1fr 1fr; }
  .related-grid { grid-template-columns: 1fr; }
  .property-types-grid { grid-template-columns: repeat(3, 1fr); }
  .carousel-slide { min-width: calc(50% - 12px); }
}

@media (max-width: 640px) {
  .section { padding: 64px 0; }
  .section-lg { padding: 80px 0; }
  h1 { font-size: 1.75rem; }
  h2 { font-size: 1.5rem; }
  .hero { min-height: 520px; }
  .hero-content { padding: 56px 0; }
  .insights-grid { grid-template-columns: 1fr; }
  .service-grid { grid-template-columns: 1fr; }
  .commitment-grid { grid-template-columns: 1fr; }
  .capabilities-grid { grid-template-columns: 1fr; }
  .latest-insights-grid { grid-template-columns: 1fr; }
  .property-types-grid { grid-template-columns: repeat(2, 1fr); }
  .newsletter-inner { flex-direction: column; align-items: flex-start; }
  .newsletter-form { flex-direction: column; max-width: 100%; }
  .newsletter-input { border-right: 1px solid rgba(255,255,255,.2); border-radius: 4px; }
  .newsletter-btn { border-radius: 4px; }
  .banner-inner { flex-direction: column; gap: 8px; }
  .tabs-layout { grid-template-columns: 1fr; }
  .tab-nav { flex-direction: row; overflow-x: auto; }
  .tab-btn { padding: 16px 20px; border-left: 0; border-bottom: 3px solid transparent; min-width: 140px; }
  .tab-btn.active { border-left: 0; border-bottom-color: var(--gold); }
  .tab-panel { padding: 28px 24px; }
  .about-stat-row { flex-direction: column; gap: 12px; }
  .carousel-slide { min-width: 100%; }
  .cta-band { padding: 56px 0; }
  .footer-grid { grid-template-columns: 1fr 1fr; gap: 28px; }
  .footer-bottom { flex-direction: column; align-items: flex-start; }
  .hero-actions { flex-direction: column; align-items: flex-start; }
}

/* ============================================================
   UTILITY
   ============================================================ */
.divider { height: 1px; background: var(--gray-200); margin: 0; }
.text-gold { color: var(--gold); }
.text-white { color: var(--white); }
.mt-auto { margin-top: auto; }
.visually-hidden { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }

raw_arguments.content:
/* ============================================================
   GlobalStone — Shared Stylesheet
   ============================================================ */

/* ---- Custom Properties ---- */
:root {
  --navy:       #0A1628;
  --navy-light: #0f2040;
  --navy-mid:   #152a52;
  --gold:       #C9A84C;
  --gold-light: #dfc06e;
  --gold-dark:  #a8882d;
  --white:      #ffffff;
  --gray-50:    #f9fafb;
  --gray-100:   #f3f4f6;
  --gray-200:   #e5e7eb;
  --gray-300:   #d1d5db;
  --gray-400:   #9ca3af;
  --gray-500:   #6b7280;
  --gray-600:   #4b5563;
  --gray-700:   #374151;
  --gray-800:   #1f2937;
  --text:       #1a2035;
  --font-sans:  'Inter', system-ui, -apple-system, sans-serif;
  --shadow-sm:  0 1px 3px rgba(0,0,0,.08), 0 1px 2px rgba(0,0,0,.05);
  --shadow-md:  0 4px 16px rgba(0,0,0,.1);
  --shadow-lg:  0 12px 40px rgba(0,0,0,.16);
  --transition: 220ms cubic-bezier(.4,0,.2,1);
  --container:  1280px;
  --radius:     4px;
}

/* ---- Reset ---- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; -webkit-text-size-adjust: 100%; }
body {
  font-family: var(--font-sans);
  font-size: 16px;
  line-height: 1.6;
  color: var(--text);
  background: var(--white);
  -webkit-font-smoothing: antialiased;
}
img { max-width: 100%; height: auto; display: block; }
a { color: inherit; text-decoration: none; }
ul, ol { list-style: none; }
button { cursor: pointer; border: none; background: none; font: inherit; }
input, textarea, select { font: inherit; }

/* ---- Layout ---- */
.container {
  width: 100%;
  max-width: var(--container);
  margin: 0 auto;
  padding: 0 24px;
}

/* ---- Typography ---- */
h1, h2, h3, h4, h5 {
  font-weight: 700;
  line-height: 1.2;
  letter-spacing: -0.02em;
  color: var(--navy);
}
h1 { font-size: clamp(2rem, 5vw, 3.5rem); }
h2 { font-size: clamp(1.75rem, 3.5vw, 2.75rem); }
h3 { font-size: clamp(1.25rem, 2.5vw, 1.75rem); }
h4 { font-size: 1.125rem; font-weight: 600; }
h5 { font-size: 0.875rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.1em; }
p { color: var(--gray-600); line-height: 1.75; }
.lead { font-size: 1.125rem; color: var(--gray-500); }

/* ---- Buttons ---- */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 13px 28px;
  font-size: 0.875rem;
  font-weight: 600;
  letter-spacing: 0.03em;
  border-radius: var(--radius);
  transition: var(--transition);
  white-space: nowrap;
}
.btn-primary {
  background: var(--gold);
  color: var(--navy);
}
.btn-primary:hover {
  background: var(--gold-light);
  transform: translateY(-1px);
  box-shadow: 0 8px 24px rgba(201,168,76,.35);
}
.btn-outline {
  background: transparent;
  color: var(--white);
  border: 1.5px solid rgba(255,255,255,.6);
}
.btn-outline:hover {
  background: rgba(255,255,255,.1);
  border-color: var(--white);
}
.btn-outline-dark {
  background: transparent;
  color: var(--navy);
  border: 1.5px solid var(--navy);
}
.btn-outline-dark:hover {
  background: var(--navy);
  color: var(--white);
}
.btn-ghost {
  padding: 0;
  color: var(--gold);
  font-weight: 600;
  font-size: 0.875rem;
}
.btn-ghost:hover { color: var(--gold-dark); }
.btn-ghost::after { content: ' →'; }

/* ---- Tag / Label ---- */
.tag {
  display: inline-block;
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  padding: 3px 10px;
  border-radius: 2px;
}
.tag-gold { background: rgba(201,168,76,.15); color: var(--gold-dark); }
.tag-navy { background: var(--navy); color: var(--white); }
.tag-gray { background: var(--gray-100); color: var(--gray-600); }

/* ============================================================
   HEADER / NAVIGATION
   ============================================================ */
.site-header {
  position: fixed;
  top: 0; left: 0; right: 0;
  z-index: 1000;
  background: var(--navy);
  border-bottom: 1px solid rgba(255,255,255,.08);
  transition: box-shadow var(--transition);
}
.site-header.scrolled {
  box-shadow: 0 4px 30px rgba(0,0,0,.4);
}
.header-inner {
  display: flex;
  align-items: center;
  height: 72px;
  gap: 40px;
}

/* Logo */
.logo {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-shrink: 0;
  text-decoration: none;
}
.logo-mark {
  width: 36px;
  height: 36px;
  background: var(--gold);
  border-radius: 3px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.logo-mark svg { width: 20px; height: 20px; fill: var(--navy); }
.logo-text {
  font-size: 1.1rem;
  font-weight: 800;
  color: var(--white);
  letter-spacing: 0.04em;
}
.logo-sub {
  display: block;
  font-size: 0.55rem;
  font-weight: 500;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: rgba(255,255,255,.5);
  margin-top: 1px;
}

/* Primary nav */
.primary-nav { flex: 1; display: flex; justify-content: center; }
.nav-list {
  display: flex;
  align-items: center;
  gap: 4px;
}
.nav-item { position: relative; }
.nav-link {
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 8px 14px;
  font-size: 0.875rem;
  font-weight: 500;
  color: rgba(255,255,255,.8);
  border-radius: var(--radius);
  transition: color var(--transition), background var(--transition);
  white-space: nowrap;
}
.nav-link:hover, .nav-link.active {
  color: var(--white);
  background: rgba(255,255,255,.08);
}
.nav-link .chevron {
  width: 14px;
  height: 14px;
  transition: transform var(--transition);
  opacity: .6;
}
.nav-item.open .nav-link .chevron { transform: rotate(180deg); }

/* Header actions */
.header-actions {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-shrink: 0;
}
.header-search {
  width: 32px; height: 32px;
  display: flex; align-items: center; justify-content: center;
  color: rgba(255,255,255,.6);
  border-radius: var(--radius);
  transition: var(--transition);
}
.header-search:hover { color: var(--white); background: rgba(255,255,255,.1); }
.header-search svg { width: 17px; height: 17px; }

/* Hamburger */
.hamburger {
  display: none;
  flex-direction: column;
  justify-content: center;
  gap: 5px;
  width: 36px;
  height: 36px;
  padding: 6px;
}
.hamburger span {
  display: block;
  height: 2px;
  background: var(--white);
  border-radius: 2px;
  transition: var(--transition);
}
.hamburger.open span:nth-child(1) { transform: rotate(45deg) translate(5px, 5px); }
.hamburger.open span:nth-child(2) { opacity: 0; }
.hamburger.open span:nth-child(3) { transform: rotate(-45deg) translate(5px, -5px); }

/* ============================================================
   MEGA MENU
   ============================================================ */
.mega-menu {
  position: absolute;
  top: calc(100% + 8px);
  left: 50%;
  transform: translateX(-50%);
  width: 620px;
  background: var(--white);
  border-radius: 8px;
  box-shadow: var(--shadow-lg);
  border: 1px solid var(--gray-200);
  padding: 28px;
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transform: translateX(-50%) translateY(-8px);
  transition: opacity 200ms ease, transform 200ms ease, visibility 200ms;
}
.mega-menu::before {
  content: '';
  position: absolute;
  top: -6px; left: 50%;
  transform: translateX(-50%);
  border: 6px solid transparent;
  border-top: 0;
  border-bottom-color: var(--white);
}
.nav-item.open .mega-menu,
.nav-item:hover .mega-menu {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
  transform: translateX(-50%) translateY(0);
}
.mega-menu-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 32px;
}
.mega-col-title {
  font-size: 0.65rem;
  font-weight: 700;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--gray-400);
  margin-bottom: 12px;
  padding-bottom: 8px;
  border-bottom: 1px solid var(--gray-200);
}
.mega-link {
  display: block;
  padding: 7px 0;
  font-size: 0.875rem;
  color: var(--gray-700);
  border-bottom: 1px solid transparent;
  transition: color var(--transition);
}
.mega-link:hover { color: var(--navy); font-weight: 600; }
.mega-link-featured {
  font-weight: 600;
  color: var(--navy);
}

/* ============================================================
   MOBILE NAV
   ============================================================ */
.mobile-nav {
  display: none;
  position: fixed;
  top: 72px; left: 0; right: 0; bottom: 0;
  background: var(--navy);
  overflow-y: auto;
  z-index: 999;
  padding: 20px 24px 40px;
}
.mobile-nav.open { display: block; }

.mobile-nav-item { border-bottom: 1px solid rgba(255,255,255,.08); }
.mobile-nav-toggle {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 16px 0;
  color: var(--white);
  font-size: 1rem;
  font-weight: 500;
  text-align: left;
}
.mobile-nav-toggle .chevron {
  width: 16px; height: 16px;
  transition: transform var(--transition);
  opacity: .5;
}
.mobile-nav-item.open .mobile-nav-toggle .chevron { transform: rotate(180deg); }
.mobile-sub {
  display: none;
  padding: 0 0 16px 16px;
}
.mobile-nav-item.open .mobile-sub { display: block; }
.mobile-sub-title {
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--gold);
  margin: 12px 0 8px;
}
.mobile-sub a {
  display: block;
  padding: 8px 0;
  font-size: 0.9rem;
  color: rgba(255,255,255,.7);
}
.mobile-sub a:hover { color: var(--white); }
.mobile-plain-link {
  display: block;
  padding: 16px 0;
  color: var(--white);
  font-size: 1rem;
  font-weight: 500;
  border-bottom: 1px solid rgba(255,255,255,.08);
}

/* ============================================================
   HERO SECTIONS
   ============================================================ */
.hero {
  position: relative;
  min-height: 620px;
  display: flex;
  align-items: center;
  overflow: hidden;
  margin-top: 72px;
}
.hero-bg {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, #0A1628 0%, #0d2742 45%, #152a52 100%);
}
.hero-bg::after {
  content: '';
  position: absolute;
  inset: 0;
  background: url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%23ffffff' fill-opacity='0.03'%3E%3Cpath d='M36 34v-4h-2v4h-4v2h4v4h2v-4h4v-2h-4zm0-30V0h-2v4h-4v2h4v4h2V6h4V4h-4zM6 34v-4H4v4H0v2h4v4h2v-4h4v-2H6zM6 4V0H4v4H0v2h4v4h2V6h4V4H6z'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E");
}
.hero-accent {
  position: absolute;
  bottom: -80px; right: -80px;
  width: 500px; height: 500px;
  background: radial-gradient(circle, rgba(201,168,76,.12) 0%, transparent 70%);
  border-radius: 50%;
}
.hero-accent-2 {
  position: absolute;
  top: -60px; left: 20%;
  width: 400px; height: 400px;
  background: radial-gradient(circle, rgba(255,255,255,.04) 0%, transparent 70%);
  border-radius: 50%;
}
.hero-content {
  position: relative;
  z-index: 1;
  max-width: 760px;
  padding: 80px 0;
}
.hero-eyebrow {
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--gold);
  margin-bottom: 20px;
}
.hero h1 { color: var(--white); margin-bottom: 20px; }
.hero .lead { color: rgba(255,255,255,.75); margin-bottom: 36px; max-width: 580px; }
.hero-actions { display: flex; gap: 14px; flex-wrap: wrap; }

/* Interior page hero */
.hero-interior { min-height: 380px; }
.hero-interior .hero-content { padding: 60px 0; }
.hero-interior h1 { font-size: clamp(1.75rem, 4vw, 2.75rem); }

/* Hero image variant */
.hero-with-image { background: none; }
.hero-with-image .hero-bg {
  background: linear-gradient(105deg, #071020 0%, #0a1628 60%, #0f1f3d 100%);
}

/* ============================================================
   SECTIONS — SHARED
   ============================================================ */
.section { padding: 96px 0; }
.section-sm { padding: 64px 0; }
.section-lg { padding: 120px 0; }
.section-dark { background: var(--navy); }
.section-dark h2, .section-dark h3, .section-dark h4 { color: var(--white); }
.section-dark p { color: rgba(255,255,255,.65); }
.section-gray { background: var(--gray-50); }
.section-header { margin-bottom: 56px; }
.section-header.centered { text-align: center; }
.section-header p { margin-top: 12px; max-width: 640px; }
.section-header.centered p { margin-inline: auto; }
.eyebrow {
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--gold);
  margin-bottom: 12px;
  display: block;
}

/* ============================================================
   FEATURED INSIGHTS — HOMEPAGE
   ============================================================ */
.featured-insights { padding: 64px 0; background: var(--gray-50); }
.insights-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}
.insight-card {
  background: var(--white);
  border-radius: 6px;
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--gray-200);
  transition: transform var(--transition), box-shadow var(--transition);
  display: flex;
  flex-direction: column;
}
.insight-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
}
.insight-card-img {
  aspect-ratio: 16/10;
  position: relative;
  overflow: hidden;
}
.insight-card-img-bg {
  position: absolute; inset: 0;
  background: linear-gradient(135deg, var(--navy) 0%, var(--navy-mid) 100%);
}
.insight-card-img-bg.var-1 { background: linear-gradient(135deg, #0f2040 0%, #1a3461 100%); }
.insight-card-img-bg.var-2 { background: linear-gradient(135deg, #0d1f38 0%, #152a52 100%); }
.insight-card-img-bg.var-3 { background: linear-gradient(135deg, #071020 0%, #0f2040 100%); }
.insight-card-img-bg::before {
  content: '';
  position: absolute; inset: 0;
  background: url("data:image/svg+xml,%3Csvg width='80' height='80' viewBox='0 0 80 80' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='%23ffffff' fill-opacity='0.05'%3E%3Cpath fill-rule='evenodd' d='M11 0l5 20H6l5-20zm42 31a3 3 0 1 0 0-6 3 3 0 0 0 0 6zM0 72h40v4H0v-4zm0-8h31.999v4H0v-4zm20-16h20v4H20v-4zM0 56h40v4H0v-4zm63-25a3 3 0 1 0 0-6 3 3 0 0 0 0 6zm10 0a3 3 0 1 0 0-6 3 3 0 0 0 0 6zM34 0l5 20h-9l4-20zm-4 0l5 20h-9l4-20zM21 0l5 20h-9l4-20z'/%3E%3C/g%3E%3C/svg%3E");
}
.insight-card-body { padding: 24px; flex: 1; display: flex; flex-direction: column; }
.insight-card-type {
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--gold-dark);
  margin-bottom: 10px;
}
.insight-card-body h4 {
  font-size: 1rem;
  font-weight: 600;
  color: var(--navy);
  line-height: 1.4;
  margin-bottom: 12px;
  flex: 1;
}
.insight-card-body .btn-ghost { margin-top: auto; }

/* ============================================================
   ANNOUNCEMENT BANNER
   ============================================================ */
.announcement-banner {
  background: var(--gold);
  padding: 16px 0;
}
.banner-inner {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 20px;
  text-align: center;
}
.banner-inner p {
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--navy);
  margin: 0;
}
.banner-cta {
  font-size: 0.8rem;
  font-weight: 700;
  color: var(--navy);
  text-decoration: underline;
  white-space: nowrap;
}
.banner-cta:hover { opacity: .7; }

/* ============================================================
   ABOUT STATEMENT
   ============================================================ */
.about-statement { padding: 96px 0; }
.about-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  align-items: center;
}
.about-text h2 { margin-bottom: 20px; }
.about-text p { margin-bottom: 32px; font-size: 1.05rem; }
.about-visual {
  position: relative;
  aspect-ratio: 4/3;
  border-radius: 8px;
  overflow: hidden;
}
.about-visual-bg {
  position: absolute; inset: 0;
  background: linear-gradient(135deg, var(--navy) 0%, var(--navy-mid) 50%, #1e3a6e 100%);
}
.about-visual-bg::before {
  content: '';
  position: absolute; inset: 0;
  background: url("data:image/svg+xml,%3Csvg width='100' height='100' viewBox='0 0 100 100' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M11 18c3.866 0 7-3.134 7-7s-3.134-7-7-7-7 3.134-7 7 3.134 7 7 7zm48 25c3.866 0 7-3.134 7-7s-3.134-7-7-7-7 3.134-7 7 3.134 7 7 7zm-43-7c1.657 0 3-1.343 3-3s-1.343-3-3-3-3 1.343-3 3 1.343 3 3 3zm63 31c1.657 0 3-1.343 3-3s-1.343-3-3-3-3 1.343-3 3 1.343 3 3 3zM34 90c1.657 0 3-1.343 3-3s-1.343-3-3-3-3 1.343-3 3 1.343 3 3 3zm56-76c1.657 0 3-1.343 3-3s-1.343-3-3-3-3 1.343-3 3 1.343 3 3 3zM12 86c2.21 0 4-1.79 4-4s-1.79-4-4-4-4 1.79-4 4 1.79 4 4 4zm28-65c2.21 0 4-1.79 4-4s-1.79-4-4-4-4 1.79-4 4 1.79 4 4 4zm23-11c2.76 0 5-2.24 5-5s-2.24-5-5-5-5 2.24-5 5 2.24 5 5 5zm-6 60c2.21 0 4-1.79 4-4s-1.79-4-4-4-4 1.79-4 4 1.79 4 4 4zm29 22c2.76 0 5-2.24 5-5s-2.24-5-5-5-5 2.24-5 5 2.24 5 5 5zM32 63c2.76 0 5-2.24 5-5s-2.24-5-5-5-5 2.24-5 5 2.24 5 5 5zm57-13c2.76 0 5-2.24 5-5s-2.24-5-5-5-5 2.24-5 5 2.24 5 5 5zm-9-21c1.105 0 2-.895 2-2s-.895-2-2-2-2 .895-2 2 .895 2 2 2zM60 91c1.105 0 2-.895 2-2s-.895-2-2-2-2 .895-2 2 .895 2 2 2zM35 41c1.105 0 2-.895 2-2s-.895-2-2-2-2 .895-2 2 .895 2 2 2z' fill='%23ffffff' fill-opacity='0.06' fill-rule='evenodd'/%3E%3C/svg%3E");
}
.about-stat-row {
  position: absolute;
  bottom: 0; left: 0; right: 0;
  background: rgba(10,22,40,.85);
  backdrop-filter: blur(8px);
  padding: 20px 24px;
  display: flex;
  gap: 32px;
}
.about-stat-num {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--gold);
  display: block;
}
.about-stat-label {
  font-size: 0.75rem;
  color: rgba(255,255,255,.6);
  letter-spacing: 0.03em;
}

/* ============================================================
   WHAT WE DO — TABBED SECTION
   ============================================================ */
.what-we-do { background: var(--gray-50); padding: 96px 0; }
.tabs-layout {
  display: grid;
  grid-template-columns: 260px 1fr;
  gap: 0;
  background: var(--white);
  border-radius: 8px;
  overflow: hidden;
  box-shadow: var(--shadow-md);
  border: 1px solid var(--gray-200);
}
.tab-nav {
  background: var(--navy);
  display: flex;
  flex-direction: column;
}
.tab-btn {
  padding: 28px 28px;
  text-align: left;
  color: rgba(255,255,255,.6);
  font-size: 0.9rem;
  font-weight: 500;
  border-left: 3px solid transparent;
  transition: var(--transition);
  border-bottom: 1px solid rgba(255,255,255,.06);
}
.tab-btn:hover { color: var(--white); background: rgba(255,255,255,.05); }
.tab-btn.active {
  color: var(--white);
  border-left-color: var(--gold);
  background: rgba(255,255,255,.08);
}
.tab-btn span {
  display: block;
  font-size: 0.65rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--gold);
  margin-bottom: 6px;
  font-weight: 700;
}
.tab-panel { display: none; padding: 48px; flex-direction: column; justify-content: center; }
.tab-panel.active { display: flex; }
.tab-panel h3 { color: var(--navy); margin-bottom: 16px; }
.tab-panel p { font-size: 1rem; margin-bottom: 32px; max-width: 500px; }

/* ============================================================
   NEWSLETTER SECTION
   ============================================================ */
.newsletter-section { background: var(--navy); padding: 72px 0; }
.newsletter-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 40px;
}
.newsletter-text h2 { color: var(--white); margin-bottom: 10px; }
.newsletter-text p { color: rgba(255,255,255,.65); max-width: 480px; }
.newsletter-form { display: flex; gap: 0; max-width: 420px; width: 100%; }
.newsletter-input {
  flex: 1;
  padding: 14px 18px;
  background: rgba(255,255,255,.08);
  border: 1px solid rgba(255,255,255,.2);
  border-right: 0;
  border-radius: 4px 0 0 4px;
  color: var(--white);
  font-size: 0.875rem;
  outline: none;
  transition: border-color var(--transition);
}
.newsletter-input::placeholder { color: rgba(255,255,255,.4); }
.newsletter-input:focus { border-color: var(--gold); }
.newsletter-btn {
  padding: 14px 24px;
  background: var(--gold);
  color: var(--navy);
  font-size: 0.875rem;
  font-weight: 700;
  border-radius: 0 4px 4px 0;
  transition: background var(--transition);
  white-space: nowrap;
}
.newsletter-btn:hover { background: var(--gold-light); }

/* ============================================================
   LATEST INSIGHTS
   ============================================================ */
.latest-insights-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 28px;
}
.insight-row-card {
  display: flex;
  flex-direction: column;
  border: 1px solid var(--gray-200);
  border-radius: 6px;
  overflow: hidden;
  transition: box-shadow var(--transition), transform var(--transition);
}
.insight-row-card:hover { box-shadow: var(--shadow-md); transform: translateY(-3px); }
.insight-row-img {
  aspect-ratio: 16/9;
  position: relative;
  overflow: hidden;
}
.insight-row-img-bg { position: absolute; inset: 0; }
.insight-row-body { padding: 24px; flex: 1; display: flex; flex-direction: column; }
.insight-row-meta {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 12px;
  flex-wrap: wrap;
}
.insight-row-meta .date {
  font-size: 0.75rem;
  color: var(--gray-400);
}
.insight-row-body h4 {
  font-size: 1rem;
  line-height: 1.4;
  color: var(--navy);
  margin-bottom: 16px;
  flex: 1;
}
.insight-row-body .btn-ghost::after { content: ' →'; }

/* ============================================================
   OUR COMMITMENT
   ============================================================ */
.commitment-section { padding: 96px 0; background: var(--gray-50); }
.commitment-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}
.commitment-card {
  background: var(--white);
  border-radius: 6px;
  padding: 36px 28px;
  border: 1px solid var(--gray-200);
  transition: var(--transition);
}
.commitment-card:hover { box-shadow: var(--shadow-md); transform: translateY(-4px); }
.commitment-icon {
  width: 48px; height: 48px;
  background: rgba(201,168,76,.12);
  border-radius: 8px;
  display: flex; align-items: center; justify-content: center;
  margin-bottom: 20px;
}
.commitment-icon svg { width: 22px; height: 22px; stroke: var(--gold-dark); fill: none; stroke-width: 1.5; }
.commitment-card h4 { margin-bottom: 12px; }
.commitment-card p { font-size: 0.875rem; margin-bottom: 20px; }

/* ============================================================
   SERVICE CATEGORIES GRID
   ============================================================ */
.service-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 28px;
}
.service-card {
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: 8px;
  padding: 36px 32px;
  display: flex;
  flex-direction: column;
  transition: var(--transition);
  position: relative;
  overflow: hidden;
}
.service-card::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 3px;
  background: var(--gold);
  transform: scaleX(0);
  transition: transform var(--transition);
}
.service-card:hover { box-shadow: var(--shadow-lg); transform: translateY(-4px); }
.service-card:hover::before { transform: scaleX(1); }
.service-card-num {
  font-size: 2.5rem;
  font-weight: 800;
  color: rgba(201,168,76,.2);
  line-height: 1;
  margin-bottom: 16px;
  font-variant-numeric: tabular-nums;
}
.service-card h3 { font-size: 1.2rem; margin-bottom: 12px; }
.service-card p { font-size: 0.9rem; flex: 1; margin-bottom: 24px; }

/* ============================================================
   CAPABILITIES GRID
   ============================================================ */
.capabilities-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}
.capability-card {
  padding: 32px 28px;
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: 6px;
  transition: var(--transition);
}
.capability-card:hover { box-shadow: var(--shadow-md); border-color: var(--gold); }
.capability-card h4 { margin-bottom: 10px; color: var(--navy); }
.capability-card p { font-size: 0.875rem; }

/* ============================================================
   FEATURED PARTNERS / CAROUSEL
   ============================================================ */
.carousel-section { background: var(--gray-50); padding: 80px 0; }
.carousel-wrapper { position: relative; overflow: hidden; }
.carousel-track {
  display: flex;
  gap: 24px;
  transition: transform 400ms cubic-bezier(.4,0,.2,1);
}
.carousel-slide {
  min-width: calc(33.333% - 16px);
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: 8px;
  padding: 32px;
  flex-shrink: 0;
}
.carousel-slide h4 { margin-bottom: 10px; }
.carousel-slide p { font-size: 0.875rem; }
.carousel-controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  margin-top: 32px;
}
.carousel-btn {
  width: 44px; height: 44px;
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  background: var(--white);
  border: 1.5px solid var(--gray-300);
  color: var(--navy);
  transition: var(--transition);
}
.carousel-btn:hover { background: var(--navy); border-color: var(--navy); color: var(--white); }
.carousel-btn svg { width: 18px; height: 18px; }

/* ============================================================
   TESTIMONIAL
   ============================================================ */
.testimonial-section { padding: 80px 0; background: var(--navy); }
.testimonial-inner { max-width: 800px; margin: 0 auto; text-align: center; }
.testimonial-quote {
  font-size: 1.4rem;
  font-style: italic;
  font-weight: 300;
  color: rgba(255,255,255,.9);
  line-height: 1.6;
  margin-bottom: 28px;
}
.testimonial-quote::before { content: '\201C'; }
.testimonial-quote::after  { content: '\201D'; }
.testimonial-author { color: var(--gold); font-weight: 600; font-size: 0.9rem; }
.testimonial-role { color: rgba(255,255,255,.5); font-size: 0.8rem; margin-top: 4px; }

/* ============================================================
   FEATURED TOPICS / SIDEBAR
   ============================================================ */
.featured-topics-section { padding: 80px 0; }
.topics-layout {
  display: grid;
  grid-template-columns: 2fr 1fr;
  gap: 60px;
  align-items: start;
}
.topics-list { }
.topic-item {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 20px 0;
  border-bottom: 1px solid var(--gray-200);
  color: var(--navy);
  font-weight: 500;
  transition: color var(--transition);
}
.topic-item:hover { color: var(--gold-dark); }
.topic-num {
  font-size: 0.8rem;
  color: var(--gold);
  font-weight: 700;
  min-width: 28px;
}
.topics-sidebar { background: var(--gray-50); border-radius: 8px; padding: 28px; }
.topics-sidebar h5 { margin-bottom: 20px; color: var(--navy); }
.topics-sidebar a {
  display: block;
  padding: 10px 0;
  font-size: 0.875rem;
  color: var(--navy);
  border-bottom: 1px solid var(--gray-200);
  transition: color var(--transition);
}
.topics-sidebar a:hover { color: var(--gold-dark); }

/* ============================================================
   CTA BANDS
   ============================================================ */
.cta-band {
  background: linear-gradient(135deg, var(--navy) 0%, var(--navy-mid) 100%);
  padding: 80px 0;
  text-align: center;
}
.cta-band h2 { color: var(--white); margin-bottom: 16px; }
.cta-band p { color: rgba(255,255,255,.65); margin-bottom: 36px; max-width: 560px; margin-inline: auto; }
.cta-band .btn-group { display: flex; gap: 14px; justify-content: center; flex-wrap: wrap; }
.cta-band-gold { background: var(--gold); }
.cta-band-gold h2 { color: var(--navy); }
.cta-band-gold p { color: rgba(10,22,40,.7); }

/* Property types */
.property-types-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 16px;
  margin-top: 48px;
}
.property-type-card {
  background: rgba(255,255,255,.08);
  border: 1px solid rgba(255,255,255,.12);
  border-radius: 6px;
  padding: 24px 16px;
  text-align: center;
  color: rgba(255,255,255,.8);
  font-size: 0.875rem;
  font-weight: 500;
  transition: var(--transition);
}
.property-type-card:hover { background: rgba(255,255,255,.14); color: var(--white); }
.property-type-icon { font-size: 1.8rem; margin-bottom: 8px; }

/* Related services */
.related-services-section { padding: 80px 0; }
.related-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}
.related-card {
  padding: 28px;
  border: 1px solid var(--gray-200);
  border-radius: 6px;
  transition: var(--transition);
}
.related-card:hover { box-shadow: var(--shadow-md); border-color: rgba(201,168,76,.4); }
.related-card h4 { font-size: 1rem; margin-bottom: 8px; }
.related-card p { font-size: 0.85rem; margin-bottom: 16px; }

/* ============================================================
   PARTNERSHIP HIGHLIGHT
   ============================================================ */
.partnership-section { background: var(--gray-50); padding: 80px 0; }
.partnership-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}
.stat-chips { display: flex; gap: 20px; margin-top: 32px; flex-wrap: wrap; }
.stat-chip {
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: 8px;
  padding: 20px 24px;
  text-align: center;
  min-width: 120px;
}
.stat-chip-num { font-size: 2rem; font-weight: 800; color: var(--gold-dark); display: block; }
.stat-chip-label { font-size: 0.75rem; color: var(--gray-500); }

/* ============================================================
   FOOTER
   ============================================================ */
.site-footer {
  background: var(--navy);
  padding: 72px 0 0;
  border-top: 1px solid rgba(255,255,255,.08);
}
.footer-grid {
  display: grid;
  grid-template-columns: 260px repeat(4, 1fr);
  gap: 40px;
  padding-bottom: 56px;
}
.footer-brand .logo { margin-bottom: 16px; }
.footer-brand p { color: rgba(255,255,255,.45); font-size: 0.8rem; line-height: 1.7; max-width: 200px; }
.footer-col h5 {
  font-size: 0.65rem;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: rgba(255,255,255,.35);
  margin-bottom: 16px;
  padding-bottom: 8px;
  border-bottom: 1px solid rgba(255,255,255,.08);
}
.footer-col a {
  display: block;
  padding: 5px 0;
  font-size: 0.85rem;
  color: rgba(255,255,255,.55);
  transition: color var(--transition);
}
.footer-col a:hover { color: var(--white); }
.footer-bottom {
  border-top: 1px solid rgba(255,255,255,.08);
  padding: 20px 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  flex-wrap: wrap;
}
.footer-bottom p { font-size: 0.78rem; color: rgba(255,255,255,.3); margin: 0; }
.footer-legal { display: flex; gap: 20px; flex-wrap: wrap; }
.footer-legal a { font-size: 0.78rem; color: rgba(255,255,255,.3); transition: color var(--transition); }
.footer-legal a:hover { color: rgba(255,255,255,.6); }

/* ============================================================
   INTRO STATEMENT BLOCK
   ============================================================ */
.intro-statement { padding: 64px 0; border-bottom: 1px solid var(--gray-200); }
.intro-statement-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  align-items: center;
}
.intro-statement h2 { margin-bottom: 16px; }
.intro-statement p { font-size: 1.05rem; }

/* ============================================================
   RESPONSIVE
   ============================================================ */
@media (max-width: 1024px) {
  .footer-grid { grid-template-columns: 1fr 1fr; gap: 32px; }
  .about-inner { grid-template-columns: 1fr; gap: 48px; }
  .about-visual { max-height: 300px; }
  .intro-statement-inner { grid-template-columns: 1fr; gap: 32px; }
  .topics-layout { grid-template-columns: 1fr; }
  .partnership-inner { grid-template-columns: 1fr; gap: 40px; }
}

@media (max-width: 900px) {
  .primary-nav { display: none; }
  .hamburger { display: flex; }
  .mega-menu { display: none !important; }

  .header-actions .btn { display: none; }

  .insights-grid { grid-template-columns: 1fr 1fr; }
  .service-grid { grid-template-columns: 1fr 1fr; }
  .commitment-grid { grid-template-columns: 1fr 1fr; }
  .capabilities-grid { grid-template-columns: 1fr 1fr; }
  .latest-insights-grid { grid-template-columns: 1fr 1fr; }
  .related-grid { grid-template-columns: 1fr; }
  .property-types-grid { grid-template-columns: repeat(3, 1fr); }
  .carousel-slide { min-width: calc(50% - 12px); }
}

@media (max-width: 640px) {
  .section { padding: 64px 0; }
  .section-lg { padding: 80px 0; }
  h1 { font-size: 1.75rem; }
  h2 { font-size: 1.5rem; }
  .hero { min-height: 520px; }
  .hero-content { padding: 56px 0; }
  .insights-grid { grid-template-columns: 1fr; }
  .service-grid { grid-template-columns: 1fr; }
  .commitment-grid { grid-template-columns: 1fr; }
  .capabilities-grid { grid-template-columns: 1fr; }
  .latest-insights-grid { grid-template-columns: 1fr; }
  .property-types-grid { grid-template-columns: repeat(2, 1fr); }
  .newsletter-inner { flex-direction: column; align-items: flex-start; }
  .newsletter-form { flex-direction: column; max-width: 100%; }
  .newsletter-input { border-right: 1px solid rgba(255,255,255,.2); border-radius: 4px; }
  .newsletter-btn { border-radius: 4px; }
  .banner-inner { flex-direction: column; gap: 8px; }
  .tabs-layout { grid-template-columns: 1fr; }
  .tab-nav { flex-direction: row; overflow-x: auto; }
  .tab-btn { padding: 16px 20px; border-left: 0; border-bottom: 3px solid transparent; min-width: 140px; }
  .tab-btn.active { border-left: 0; border-bottom-color: var(--gold); }
  .tab-panel { padding: 28px 24px; }
  .about-stat-row { flex-direction: column; gap: 12px; }
  .carousel-slide { min-width: 100%; }
  .cta-band { padding: 56px 0; }
  .footer-grid { grid-template-columns: 1fr 1fr; gap: 28px; }
  .footer-bottom { flex-direction: column; align-items: flex-start; }
  .hero-actions { flex-direction: column; align-items: flex-start; }
}

/* ============================================================
   UTILITY
   ============================================================ */
.divider { height: 1px; background: var(--gray-200); margin: 0; }
.text-gold { color: var(--gold); }
.text-white { color: var(--white); }
.mt-auto { margin-top: auto; }
.visually-hidden { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }

